// ================= V2 上下文感知优化 · 运行时（阶段 A/B/C） =================
// v2.0.0 方案 §3：阶段 A 任务进度（smart LLM / basic 规则）→ 阶段 B 相关性检索
// （工作区文件 + 会话事件）→ 阶段 C 预算组装注入。各阶段独立降级，不阻断优化。
// v2.4.6：TASK_ANALYSIS_PROMPT / CONTEXT_GUARD 已外置 prompts/*.md（见生成标记区）。

const V2_WORKSPACE_IGNORE_DIRS = new Set(['node_modules', '.git', 'dist', 'build', '.venv', 'venv', '__pycache__', '.next', '.cache', 'coverage', 'target', '.idea', '.vscode']);

// P0-b 修正（2026-10-12 · 第三轮 · 独立复核 blocker）：非 LLM 等待（sessionQuery / fs / web.search）
// 的超时此前一律是「只置标志位」，而 `await` 会一直等到该调用自己返回 ⇒ 慢调用可越过自己的
// 钳后超时、吃掉总预算并侵蚀生成额度（复核实测：readSurface 慢 23s/24s/30s ⇒ 改后 TIMEOUT、
// genCalls=0，HEAD 为 ok:true）。此处把 LLM 腿的 startHelperAbort 语义推广为**同一套** race+dispose：
//   · 到点 → 置标志 + **立即以超时结算**（调用方按降级继续，不再等底层返回）；
//   · 到点后底层 promise 迟到 settle → `.then(noop, noop)` 吞掉，**不产生 unhandledRejection**；
//   · dispose() → 清 timer，并吞掉最终 settle（幂等，可重复调用）。
// ⚠ 与 LLM 腿的差异（如实声明）：LLM 腿可经 `iterator.return()` 通知官方适配器停止产出；
//   sessionQuery/fs/web 的公开签名**不接受 AbortSignal**（dsh-tool-cordis api-catalog：
//   `readSurface(sessionId)` / `listEvents(sessionId)` / `filterEvents(sessionId, filters)` 均无 signal），
//   故这里只能做到「**不等它**」——底层工作是否真正释放由宿主实现决定，本层无法保证（见测试内边界注记）。
function startWaitAbort(timerSvc, ms) {
  let fired = false;
  let settled = false;
  let fireTimer = null;
  let settle = null;
  const work = [];
  const gate = new Promise((resolve) => { settle = resolve; });
  const fire = () => {
    if (settled) return;
    fired = true;
    settled = true;
    try { settle({ timedOut: true }); } catch (e) { /* 忽略 */ }
    // 到点后底层迟到 settle：吞掉，防 unhandledRejection
    for (const p of work) {
      if (p && typeof p.then === 'function') { try { p.then(noop, noop); } catch (e) { /* 忽略 */ } }
    }
  };
  const noop = () => {};
  const n = typeof ms === 'number' && Number.isFinite(ms) ? Math.max(0, ms) : 0;
  if (n > 0 && timerSvc && typeof timerSvc.timeout === 'function') {
    fireTimer = timerSvc.timeout(fire, n);
  } else {
    fire();  // 预算已耗尽 / 无 timer 服务 → 立即超时（调用方直接走降级）
  }
  return {
    timedOut: () => fired,
    // 把底层 promise 纳入「迟到吞掉」集合后 race；早于闸门 settle 则返回其真值。
    race: (p) => {
      if (p && typeof p.then === 'function') {
        work.push(p);
        if (fired) { try { p.then(noop, noop); } catch (e) { /* 忽略 */ } }
      }
      return Promise.race([p, gate]);
    },
    dispose: () => {
      try { if (fireTimer) fireTimer(); } catch (e) { /* 忽略 */ }
      settled = true;
    },
  };
}

// 阶段 A：任务进度理解（表驱动 phaseA：none 跳过 / rule 正则 / llm 智能（失败降级 rule）/ memory 读记忆对）
// 返回值：{ progress, mode }；mode: 'smart'|'rule'|'memory'|'none'
async function v2ResolveProgress(services, historyText, cfg) {
  // P0-d（2026-10-12 · 独立复核 medium）：本函数是 5 处辅助 LLM 调用之一，原先失败**只写 hlog**
  // （用户侧零痕迹），且不接 state/rec。现经 services.onDegrade 回调把降级回传到 enhance handler。
  const degrade = (kind) => {
    if (services && typeof services.onDegrade === 'function') {
      try { services.onDegrade('v2progress-' + kind); } catch (e) { /* 忽略 */ }
    }
  };
  const row = MODE_TABLE[cfg.mode] || MODE_TABLE[DEFAULT_MODE];
  if (row.phaseA === 'llm' && services.llm && services.chain && services.chain.length > 0 && historyText.trim() !== '') {
    const entry = services.chain[0];
    let timedOut = false;
    // P0-b（2026-10-12 · 辅助调用并入同一预算）：自身 15s 超时钳到剩余主预算内
    // （services.budgetDeadline 由 enhance handler 传入；未设预算 → Infinity，行为不变）。
    const remainMs = (typeof services.budgetDeadline === 'number')
      ? Math.max(0, services.budgetDeadline - Date.now())
      : Infinity;
    const progressTimeoutMs = remainMs === Infinity ? V2_PROGRESS_TIMEOUT_MS : Math.max(0, Math.min(V2_PROGRESS_TIMEOUT_MS, remainMs));
    // P0-b 修正（2026-10-12 · 独立复核 blocker）：超时到点须**真正中止**该辅助流，
    // 否则慢但健康的辅助会跑过自己的钳后超时、侵蚀生成额度（见 enhance-handlers.js startHelperAbort 注释）。
    let abortIterator = null;
    let settleTimeout = null;
    const timeoutGate = new Promise((resolve) => { settleTimeout = resolve; });
    const fireAbort = () => {
      timedOut = true;
      if (abortIterator && typeof abortIterator.return === 'function') {
        try { abortIterator.return(); } catch (e) { /* 忽略 */ }
      }
      try { settleTimeout({ kind: 'aborted', aborted: true }); } catch (e) { /* 忽略 */ }
    };
    const timer = progressTimeoutMs > 0
      ? services.timer.timeout(fireAbort, progressTimeoutMs)
      : (fireAbort(), () => {});
    try {
      const stream = services.llm.stream({
        provider: entry.provider,
        model: entry.model,
        // v3.0p 审查（超时/耗时匹配）：阶段 A 任务分析剥离 reasoningEffort（同 judge 策略）
        maxTokens: V2_PROGRESS_MAX_TOKENS,
        system: TASK_ANALYSIS_PROMPT,
        messages: [{
          id: 'enhance-task-progress',
          role: 'user',
          content: [{ type: 'text', text: historyText.slice(0, V2_HISTORY_MAX_CHARS) }],
          source: { kind: 'user' },
        }],
      });
      const iterator = stream[Symbol.asyncIterator]();
      abortIterator = iterator;
      if (timedOut) fireAbort();
      const collectP = collectStream(iterator, V2_PROGRESS_OUTPUT_LIMIT);
      collectP.catch(() => { /* 超时闸先结算时 collectP 可能随后 reject */ });
      const result = await Promise.race([collectP, timeoutGate]);
      // P0-e（消费点 1/6）：max-tokens 现返回可区分 kind 'maxtokens'；阶段 A 任务分析
      // **按原样透传**（非 ok 一律走降级日志/规则兜底）——显式声明，不静默沿用旧兜底。
      if (!timedOut && result.kind === 'ok') {
        const parsed = parseTaskProgress(result.text);
        if (parsed) {
          hlog('[enhance] v2 smart progress ok');
          return { progress: parsed, mode: 'smart' };
        }
        degrade('bad-json');
        hlog('[enhance] v2 smart progress bad-json');
      } else {
        // 独立复审 low（2026-10-12）：finish.kind==='error'（如 SERVER/QUOTA）此前落进 'empty'，
        // 诊断标签失准会误导排查方向——按真实 kind 分流，并带上 failure code。
        const why = timedOut ? 'timeout'
          : (result.kind === 'maxtokens' ? 'truncated'
          : (result.kind === 'error' ? ('error-' + String((result.failure && result.failure.code) || 'unknown'))
          : (result.kind === 'aborted' || result.kind === 'cancelled' ? String(result.kind) : 'empty')));
        degrade(why);
        hlog('[enhance] v2 smart progress ' + why);
      }
    } catch (e) {
      degrade('failed');
      hlog('[enhance] v2 smart progress failed', e && e.message ? e.message : e);
    } finally {
      try { timer(); } catch (e) { /* 忽略 */ }
      if (abortIterator && typeof abortIterator.return === 'function') {
        try { abortIterator.return(); } catch (e) { /* 忽略 */ }
      }
    }
  }
  // rule 规则提取（零成本；无历史时返回空 focus）——phaseA: rule / llm 降级 / memory 无记忆时兜底
  const focus = inferFocusRules(historyText);
  if (focus.length > 0) return { progress: { focus }, mode: 'rule' };
  return { progress: null, mode: 'rule' };
}

// 阶段 B：工作区文件检索（fs 扫描 + 名称/内容命中 → Top-3 摘要；2s 超时降级）
// v2.0.7：fs 契约修正——listDir/readText 接收 FsTarget（resolve 产出），条目 shape 为
// {name, type:'file'|'directory', target}；不再传字符串路径。
async function v2SearchWorkspace(services, keywords, cfg) {
  const fsSvc = services.fs;
  const root = services.sandboxPolicy && services.sandboxPolicy.workspaceRoot;
  if (!fsSvc || !root || typeof fsSvc.listDir !== 'function' || typeof fsSvc.readText !== 'function' || typeof fsSvc.resolve !== 'function') return [];
  // 表驱动：phaseB 非 file+event 跳过；扫描上限按 scanLimit（by-budget 查联动表 / fixed 固定）
  const row = MODE_TABLE[cfg.mode] || MODE_TABLE[DEFAULT_MODE];
  if (row.phaseB !== 'file+event') return [];
  const lim = resolveScanLimit(cfg.mode, cfg.context.budgetChars);
  const depth = lim.depth;
  const maxFiles = lim.maxFiles;
  // P0-b 修正（第三轮）：标志位 → race+dispose（超时即不再等；到点后迟到 settle 被吞）
  const waitAbort = startWaitAbort(services.timer, V2_WORKSPACE_TIMEOUT_MS);
  const abortedFn = () => waitAbort.timedOut();
  try {
    let rootTarget;
    try {
      const rootRes = await waitAbort.race(fsSvc.resolve(root));
      if (waitAbort.timedOut()) { hlog('[enhance] v2 workspace resolve-root timeout'); return []; }
      rootTarget = rootRes;
    } catch (e) {
      hlog('[enhance] v2 workspace resolve-root failed', e && e.message ? e.message : e);
      return [];
    }
    const files = [];
    const walk = async (target, rel, level) => {
      if (abortedFn() || files.length >= SCAN_FILE_LIST_MAX || level > depth) return;
      let entries;
      try {
        // P0-b 修正（第三轮）：目录列举纳入同一 race（超时即不再等待该目录）
        entries = await waitAbort.race(fsSvc.listDir(target));
        if (waitAbort.timedOut()) return;
      } catch (e) { return; }
      for (const en of entries || []) {
        if (abortedFn()) return;
        const name = en && en.name;
        if (!name) continue;
        if (V2_WORKSPACE_IGNORE_DIRS.has(name)) continue;
        const relPath = rel ? rel + '/' + name : name;
        if (en.type === 'directory') {
          await walk(en.target, relPath, level + 1);
        } else if (en.type === 'file') {
          files.push(relPath);
        }
      }
    };
    await walk(rootTarget, '', 1);
    if (abortedFn()) { hlog('[enhance] v2 workspace scan timeout'); return []; }
    hlog('[enhance] v2 workspace scanned files=' + files.length);
    // 名称匹配 → 候选；v2.7.0：名称 0 命中时内容兜底（中文场景名称匹配几乎必然落空——
    // 中文关键词 vs 英文文件名；降级取前 N 个文本文件按内容关键词命中，救活
    // 「文件内容相关但文件名无关」场景；读取受 V2_WORKSPACE_TIMEOUT_MS 总超时保护）
    const candidates = rankFiles(files, keywords, 10).map((c) => c.path);
    if (candidates.length === 0) {
      const textRe = /\.(?:md|txt|py|ts|js|tsx|jsx|json|yaml|yml|toml|css|html|go|rs|java|cpp|c|h|sh|sql|vue)$/i;
      // 文档类（md/txt）优先——描述性内容最可能命中主题词
      const docFirst = files.slice().sort((a, b) => {
        const da = /\.(?:md|txt)$/i.test(a) ? 0 : 1;
        const db = /\.(?:md|txt)$/i.test(b) ? 0 : 1;
        return da - db;
      });
      const kws = (keywords || []).filter((k) => typeof k === 'string' && k.length >= 2);
      const contentScored = [];
      let scanned = 0;
      for (const rel of docFirst) {
        if (abortedFn() || scanned >= CONTENT_FALLBACK_SCAN) break;
        if (!textRe.test(rel) || shouldIgnoreFile(rel)) continue;
        scanned++;
        let text = '';
        try {
          // P0-b 修正（第三轮）：内容兜底读取纳入同一 race（超时即中止本轮扫描）
          const tgtRes = await waitAbort.race(fsSvc.resolve(rel, { cwd: root }));
          if (waitAbort.timedOut()) break;
          text = await waitAbort.race(fsSvc.readText(tgtRes));
          if (waitAbort.timedOut()) break;
        } catch (e) { continue; } // 只读权限/读取失败 → 跳过该文件
        const lines = text.split('\n');
        let contentHits = 0;
        for (const ln of lines) {
          if (kws.some((k) => ln.toLowerCase().includes(k.toLowerCase()))) contentHits++;
          if (contentHits >= 8) break;
        }
        if (contentHits > 0) contentScored.push({ path: rel, lines, contentHits });
      }
      hlog('[enhance] v2 workspace content-fallback scanned=' + scanned + ' hits=' + contentScored.length + ' kws=' + JSON.stringify(keywords));
      if (contentScored.length === 0) {
        hlog('[enhance] v2 workspace no-name-match files=' + files.length + ' kws=' + JSON.stringify(keywords));
        return [];
      }
      contentScored.sort((a, b) => b.contentHits - a.contentHits);
      const top = contentScored.slice(0, maxFiles);
      return top.map((f) => ({ path: f.path, snippet: snippetFromLines(f.lines, keywords, SNIPPET_BUDGET) }));
    }
    // 内容命中加分 → 排序 Top-maxFiles
    const scored = [];
    for (const rel of candidates) {
      if (abortedFn()) break;
      if (shouldIgnoreFile(rel)) continue;
      let text = '';
      try {
        // P0-b 修正（第三轮）：候选文件读取纳入同一 race
        const tgtRes = await waitAbort.race(fsSvc.resolve(rel, { cwd: root }));
        if (waitAbort.timedOut()) break;
        text = await waitAbort.race(fsSvc.readText(tgtRes));
        if (waitAbort.timedOut()) break;
      } catch (e) { continue; } // 只读权限/读取失败 → 跳过该文件
      const lines = text.split('\n');
      let contentHits = 0;
      const kws = (keywords || []).filter((k) => typeof k === 'string' && k.length >= 2);
      for (const ln of lines) {
        if (kws.some((k) => ln.toLowerCase().includes(k.toLowerCase()))) contentHits++;
        if (contentHits >= 8) break;
      }
      if (contentHits > 0) scored.push({ path: rel, lines, contentHits });
    }
    if (scored.length === 0) {
      hlog('[enhance] v2 workspace no-content-match candidates=' + candidates.length + ' kws=' + JSON.stringify(keywords));
      return [];
    }
    scored.sort((a, b) => b.contentHits - a.contentHits);
    const top = scored.slice(0, maxFiles);
    return top.map((f) => ({ path: f.path, snippet: snippetFromLines(f.lines, keywords, SNIPPET_BUDGET) }));
  } finally {
    waitAbort.dispose();
  }
}

// 阶段 B3：会话事件检索（增强；searchEvents 契约：{sessionId,query,limit} → {items:[{snippet}]}；失败跳过）
async function v2SearchEvents(services, sessionId, keywords, cfg) {
  const sq = services.sessionQuery;
  const kws = (keywords || []).filter((k) => typeof k === 'string' && k.trim() !== '');
  // 表驱动：phaseB 非 file+event 跳过
  const row = MODE_TABLE[cfg.mode] || MODE_TABLE[DEFAULT_MODE];
  if (row.phaseB !== 'file+event') return [];
  if (!sq || typeof sq.searchEvents !== 'function' || kws.length === 0) {
    hlog('[enhance] v2 searchEvents skipped kws=' + kws.length);
    return [];
  }
  // v3.0p 审查（超时/耗时匹配）：searchEvents 补超时保护（10s，超时/失败 → [] 不阻断）
  // P0-b 修正（第三轮）：标志位 → race+dispose（超时即不再等；到点后迟到 settle 被吞）
  const waitAbort = startWaitAbort(services.timer, V2_SEARCH_EVENTS_TIMEOUT_MS);
  try {
    const page = await waitAbort.race(sq.searchEvents({ sessionId, query: kws.join(' '), limit: 3 }));
    if (waitAbort.timedOut()) { hlog('[enhance] v2 searchEvents timeout'); return []; }
    const hits = page && Array.isArray(page.items) ? page.items : [];
    hlog('[enhance] v2 searchEvents kws=' + JSON.stringify(kws) + ' hits=' + hits.length);
    if (hits.length === 0) return [];
    return hits.slice(0, 3).map((h) => {
      const txt = h && (typeof h.snippet === 'string' ? h.snippet : (typeof h.text === 'string' ? h.text : ''));
      return txt ? txt.slice(0, 300) : '';
    }).filter(Boolean);
  } catch (e) {
    hlog('[enhance] v2 searchEvents failed', e && e.message ? e.message : e);
    return []; // 服务缺失/请求形状不符/失败 → 跳过事件段
  } finally {
    waitAbort.dispose();
  }
}

// 阶段 A/B/C 汇总：返回 { block, log }（全部不可用 → { block: '', log: 'none' }）
// v2.2（§6.5）：4 模式管道（base/lite 空块 / standard/smart 检索）。
// v2.6.1（记忆链）：记忆不再作为文本块叠加（改由 enhance 入口以真多轮消息注入，
// 见 buildChatMessages），模式块独享预算；log 仅含模式块口径（记忆见入口 memory 日志）。
// v2.3（§7.3）：onStage 回调（由 enhance handler 注入，写 pending 记录的 stage 字段；
// 纯函数本体不接触模块状态，回调缺省为 no-op 保持 PURE 区段可切片）。
async function buildV2ContextBlock(services, sessionId, text, cfg, onStage) {
  const mark = typeof onStage === 'function' ? onStage : () => {};
  const row = MODE_TABLE[cfg.mode] || MODE_TABLE[DEFAULT_MODE];
  const budget = cfg.context.budgetChars || 0;
  // ===== 模式管道（base/lite：phaseB='none' 无检索 → 空模式块）=====
  let modeBlock = '';
  let modeLog = 'none';
  // v3.0p（publish 多步检索）：web 段结果透出（跨轮记忆用；无检索时为空）
  let webTopics = [];
  let webMemoText = '';
  if (row.phaseC === 'inject') {
    // 历史 + 阶段A + 阶段B
    let events = [];
    let historyText = '';
    const sq = services.sessionQuery;
    if (sq && typeof sq.listEvents === 'function' && typeof sq.filterEvents === 'function') {
      // P0-b 修正（2026-10-12 · 第三轮）：publish 路径的历史读取同样统一到 race+dispose
      // （此前与 fetchSessionHistory 同形：只置标志位、await 会一直等到调用返回）。
      const waitHist = startWaitAbort(services.timer, V2_SEARCH_EVENTS_TIMEOUT_MS);
      try {
        mark(STAGE_HISTORY);
        // v3.1.3（用户需求·仅结论参考）：同 v3 路径——readSurface 块级结论提取，旧路径兜底
        if (typeof sq.readSurface === 'function') {
          const surface = await waitHist.race(sq.readSurface(sessionId));
          if (waitHist.timedOut()) { hlog('[enhance] v2 history timeout'); }
          if (!waitHist.timedOut()) events = extractHistoryConclusions(surface && surface.events);
        } else {
          const records = await waitHist.race(sq.listEvents(sessionId));
          if (waitHist.timedOut()) { hlog('[enhance] v2 history timeout'); }
          // 尾部反向找最近的消息事件 seq（listEvents 升序，无文本；seq 用于 filterEvents 范围过滤）
          const msgSeqs = [];
          for (let i = (waitHist.timedOut() ? 0 : records.length - 1); i >= 0 && msgSeqs.length < V2_MSG_SEQ_SCAN; i--) {
            const r = records[i];
            const t = String(r && r.type || '');
            if (t === 'user/message' || t === 'assistant/message') msgSeqs.push(r && r.seq);
          }
          if (msgSeqs.length > 0) {
            const minSeq = msgSeqs[msgSeqs.length - 1];
            const docs = await waitHist.race(sq.filterEvents(sessionId, [{ kind: 'seq', from: minSeq }]));
            if (!waitHist.timedOut()) events = extractHistory(docs, V2_HISTORY_LIMIT);
          }
        }
        historyText = events.map((e) => (e.type === 'user' ? '[用户] ' : '[助手] ') + e.text).join('\n');
        hlog('[enhance] v2 history events=' + events.length + ' chars=' + historyText.length + (typeof sq.readSurface === 'function' ? ' conclusion-only' : ''));
      } catch (e) {
        hlog('[enhance] v2 history failed', e && e.message ? e.message : e);
      } finally {
        waitHist.dispose();
      }
    } else {
      hlog('[enhance] v2 sessionQuery unavailable');
    }
    const root = services.sandboxPolicy && services.sandboxPolicy.workspaceRoot;
    hlog('[enhance] v2 workspaceRoot=' + (root || '(none)') + ' fs=' + (services.fs ? 'yes' : 'no'));
    // 阶段 A（表驱动 phaseA：llm 智能 / rule 正则 / none 跳过）
    mark(STAGE_ANALYZE);
    const { progress, mode } = await v2ResolveProgress(services, historyText, cfg);
    // 阶段 B（表驱动 phaseB：file+event 全量 / none 跳过）
    const focus = progress && Array.isArray(progress.focus) ? progress.focus : [];
    const keywords = extractKeywords(text, focus);
    mark(STAGE_FILES, { key: 'scan' });
    const files = await v2SearchWorkspace(services, keywords, cfg);
    mark(STAGE_EVENTS);
    const eventsHits = await v2SearchEvents(services, sessionId, keywords, cfg);
    // 阶段 C（inject）：模式块独享预算（记忆链不占文本块）
    modeBlock = buildContextBlock(progress, files, eventsHits, budget);
    // v2.7.0（一键发布 · 网络检索）：publish 专属——依据草稿主题词 + 记忆链 delta
    // 改动方向构造检索词，经 ctx.web 搜索同类项目结构参考，注入模式块（预算余量内）。
    // 独立超时/降级：搜索失败/服务缺失 → 跳过，不阻断规格生成。
    let webLog = 'none';
    if (cfg.mode === 'publish' && budget > 0) {
      mark(STAGE_FILES); // 复用 files 阶段标记（检索类）
      // v3.0p（publish 多步检索）：跨轮要点回注——历史【已获取网络参考】前置（预算内），
      // 让模型「记住」此前检索到的信息，只补新缺口（配合 publishWebMemo 会话级记忆）
      if (services.webMemo) {
        const memoBlock = '【已获取网络参考】\n' + String(services.webMemo).slice(0, WEB_MEMO_MAX);
        modeBlock = modeBlock ? modeBlock + '\n\n' + memoBlock : memoBlock;
      }
      // v3.0p（publish 多步检索）：LLM 规划的差异化主题逐主题搜索（services.webPlan 非空时）；
      // 无规划 / 规划失败 → 降级旧单 query 路径（buildWebQuery + 场景方向词，行为不变）
      const web = services.web;
      const planQueries = Array.isArray(services.webPlan) && services.webPlan.length > 0
        ? services.webPlan.map((t) => String(t && t.query || '').trim()).filter((q) => q !== '').slice(0, 3)
        : [];
      const queries = planQueries.length > 0 ? planQueries : [null];
      const topicLogs = [];
      if (web && typeof web.search === 'function') {
        const refParts = [];
        const memoParts = [];
        for (let qi = 0; qi < queries.length; qi++) {
          const q = queries[qi];
          let query = q;
          if (query === null) {
            query = buildWebQuery(text, keywords, services.delta || null);
            if (services.scenario === 'game') query = (query ? query + ' 游戏实现' : '游戏实现');
            else if (services.scenario === 'software') query = (query ? query + ' 软件架构' : '软件架构');
          }
          // v3.0r（细粒度进度反馈）：逐主题搜索进度（detailKey=search，client 渲染「正在搜索 i/n：query」）
          mark(STAGE_FILES, { key: 'search', args: { query }, step: qi + 1, total: queries.length });
          // P0-b 修正（第三轮）：标志位 → race+dispose（超时即不再等该主题；迟到 settle 被吞）
          const waitAbort = startWaitAbort(services.timer, WEB_SEARCH_TIMEOUT_MS);
          try {
            const res = await waitAbort.race(web.search({ query, maxResults: WEB_SEARCH_MAX_RESULTS }));
            if (!waitAbort.timedOut() && res && Array.isArray(res.sources) && res.sources.length > 0) {
              const lines = res.sources.slice(0, WEB_SEARCH_MAX_RESULTS).map((s) => {
                const title = s && s.title ? String(s.title) : '';
                const url = s && s.url ? String(s.url) : '';
                const summary = s && s.summary ? String(s.summary).slice(0, 200) : '';
                return '- ' + title + (url ? ' (' + url + ')' : '') + (summary ? '\n  ' + summary : '');
              }).join('\n');
              refParts.push('### 检索主题：' + query + '\n' + lines);
              memoParts.push('『' + query + '』：' + res.sources.slice(0, 2).map((s) => String(s && s.title || '') + (s && s.summary ? '——' + String(s.summary).slice(0, 60) : '')).join('；'));
              topicLogs.push({ query, hits: res.sources.length });
            } else {
              topicLogs.push({ query, hits: waitAbort.timedOut() ? -2 : 0 });
            }
          } catch (e) {
            topicLogs.push({ query, hits: -1 });
          } finally {
            waitAbort.dispose();
          }
        }
        const refText = refParts.join('\n\n');
        if (refText) {
          const webBlock = '【网络参考】\n' + refText.slice(0, Math.min(WEB_REF_MAX, Math.max(0, budget - modeBlock.length)));
          if (webBlock.length > 20) {
            modeBlock = modeBlock ? modeBlock + '\n\n' + webBlock : webBlock;
            webLog = 'web=' + topicLogs.filter((t) => t.hits > 0).length + '/' + topicLogs.length + ' chars=' + webBlock.length;
          } else {
            webLog = 'web=0';
          }
        } else {
          webLog = 'web=0';
        }
        webTopics = topicLogs;
        webMemoText = memoParts.join('\n').slice(0, WEB_MEMO_MAX);
      } else {
        webLog = 'web=none';
      }
      hlog('[enhance] v2 web ' + webLog + ' queries=' + topicLogs.map((t) => t.query + ':' + t.hits).join('|').slice(0, 200));
    }    modeLog = modeBlock === '' ? 'none' : (mode + ' files=' + files.length + ' events=' + eventsHits.length + (webLog !== 'none' ? ' ' + webLog : '') + ' chars=' + modeBlock.length);
  }
  // ===== 汇总（记忆链由 enhance 入口以多轮消息注入，不占文本块）=====
  mark(STAGE_CONTEXT);
  return { block: modeBlock, log: modeBlock === '' ? 'none' : modeLog, webTopics, webMemoText };
}

function selfState(reference) {
  const status = reference.latestRun && reference.latestRun.status;
  if (status === 'awaiting-approval') return 'awaiting-approval';
  if (status === 'client-pending' || status === 'starting-host') return 'client-pending';
  if (status === 'failed' || status === 'rejected' || status === 'cancelled') return 'failed';
  if (status === 'waiting') return 'waiting';
  if (status === 'running') return 'running';
  if (reference.activeRun !== undefined) return 'running';
  return reference.currentPackageId === undefined ? 'defined' : 'stopped';
}

function summarize(reference) {
  const latest = reference.latestRun;
  const state = selfState(reference);
  return {
    pluginId: String(reference.pluginId),
    name: reference.name,
    state,
    // v2.4.3-fix：透传每包半部完整性——client 版本下拉据此禁用残缺包（防误切致 UI 消失）
    ...(reference.packages ? { packages: reference.packages.map((p) => ({ packageId: String(p.packageId), name: p.name, purpose: p.purpose || '', hasHostHalf: p.hasHostHalf === true, hasClientHalf: p.hasClientHalf === true })) } : { packages: [] }),
    ...(reference.currentPackageId === undefined ? {} : { currentPackageId: String(reference.currentPackageId) }),
    ...(reference.nextPackageId === undefined ? {} : { nextPackageId: String(reference.nextPackageId) }),
    ...(reference.activeRun === undefined ? {} : { activeRun: { pluginRunId: String(reference.activeRun.pluginRunId), packageId: String(reference.activeRun.packageId) } }),
    ...(latest && latest.status === 'awaiting-approval' ? { pendingApproval: { pluginRunId: String(latest.pluginRunId), packageId: String(latest.packageId), mode: latest.mode } } : {}),
  };
}

return {
  // #3 修复（2026-08-21）：llm 服务声明为 inject 依赖，消除启动竞态下 ctx.get('llm') 为 undefined → enhance NO_LLM
  inject: ['llm', 'timer'],
  apply(ctx) {
    const llm = ctx.get('llm');
    const pending = new Map();
    // v2.8.0（一键发布 · 场景路由）：会话级场景缓存（sessionId → game/software/generic）。
    // 首轮判定写入、后续轮读取不重判（场景决定九章骨架，翻转会推翻已确认设计）；
    // 生命周期 = 插件进程，进程重启后缓存 miss → 用记忆链最早轮输入兜底判定（enhance 内判定源规则）
    const publishScenarioCache = new Map();
    // v3.0p（publish 多步检索）：会话级网络检索记忆（sessionId → {topics[], memo}）。
    // topics = 已检索主题（去重，≤WEB_MEMO_TOPICS_MAX）；memo = 已获取要点摘要（≤WEB_MEMO_MAX，
    // 跨轮以【已获取网络参考】回注，让模型记住已查信息、只补新缺口）。
    // 生命周期 = 插件进程（同 publishScenarioCache）。
    const publishWebMemo = new Map();

    function requestKey(sessionId, seq) {
      return String(sessionId) + ':' + String(seq);
    }

    function markAndAbort(key, flag) {
      const rec = pending.get(key);
      if (!rec) return;
      rec[flag] = true;
      if (rec.iterator && typeof rec.iterator.return === 'function') {
        try { rec.iterator.return(); } catch (e) { /* 忽略 */ }
      }
    }

    function resolveAgent(sessionId) {
      const agents = ctx.get('agents');
      if (!agents || typeof agents.get !== 'function') return null;
      return agents.get(sessionId) || null;
    }

    harness.handle('models/list', async () => {
      const llmService = ctx.get('llm');
      if (!llmService || typeof llmService.listProviders !== 'function') {
        return { ok: false, code: 'NO_LLM', message: 'llm service unavailable' };
      }
      try {
        const providers = llmService.listProviders();
        const out = [];
        for (const p of providers) {
          let models = [];
          try {
            const list = await llmService.listModels(p.id);
            models = (list || []).map((m) => ({ id: m.id, name: m.name || m.id }));
          } catch (e) { models = []; }
          out.push({ provider: p.id, name: p.name, models });
        }
        return { ok: true, providers: out };
      } catch (e) {
        herr('[enhance] models/list failed', e);
        return { ok: false, code: 'MODELS_FAILED', message: String(e && e.message ? e.message : e) };
      }
    });

    harness.handle('models/resolve', async (args) => {
      const provider = args && typeof args.provider === 'string' ? args.provider : '';
      const model = args && typeof args.model === 'string' ? args.model : '';
      const llmService = ctx.get('llm');
      if (!llmService || typeof llmService.resolveModelInfo !== 'function') {
        return { ok: false, code: 'NO_LLM', message: 'llm service unavailable' };
      }
      if (!provider || !model) return { ok: false, code: 'BAD_ARGS', message: 'provider and model required' };
      try {
        // v21（P1-4）：走 TTL 缓存，避免重复适配器能力查询
        // F1（配置卫生）：noCache 旁路 TTL——client effort 纠偏场景需要新鲜能力表
        const info = await resolveModelInfoCached(llmService, provider, model, !!(args && args.noCache === true));
        const reasoning = info && info.reasoning ? {
          efforts: info.reasoning.efforts.map((e) => ({
            id: String(e.id),
            name: e.name,
            ...(e.description ? { description: e.description } : {}),
          })),
          ...(info.reasoning.defaultEffort ? { defaultEffort: String(info.reasoning.defaultEffort) } : {}),
        } : undefined;
        return {
          ok: true,
          provider,
          model,
          ...(reasoning ? { reasoning } : {}),
          ...(info && info.context ? { context: info.context } : {}),
          ...(info && info.defaultMaxTokens ? { defaultMaxTokens: info.defaultMaxTokens } : {}),
        };
      } catch (e) {
        herr('[enhance] models/resolve failed', e);
        return { ok: false, code: 'RESOLVE_FAILED', message: String(e && e.message ? e.message : e) };
      }
    });

    harness.handle('models/current', async () => {
      const adm = ctx.get('agentDefaultModel');
      if (!adm || typeof adm.currentSelection !== 'function') {
        return { ok: false, code: 'NO_SERVICE', message: 'agentDefaultModel unavailable' };
      }
      try {
        const sel = adm.currentSelection();
        if (!sel || typeof sel.provider !== 'string' || typeof sel.model !== 'string' || !sel.provider || !sel.model) {
          return { ok: false, code: 'EMPTY', message: 'no current selection' };
        }
        return {
          ok: true,
          provider: sel.provider,
          model: sel.model,
          ...(typeof sel.reasoningEffort === 'string' && sel.reasoningEffort ? { reasoningEffort: sel.reasoningEffort } : {}),
        };
      } catch (e) {
        herr('[enhance] models/current failed', e);
        return { ok: false, code: 'CURRENT_FAILED', message: String(e && e.message ? e.message : e) };
      }
    });

    // v19：暴露自适应解析出的默认兜底链（供 client 首装继承 / 恢复默认使用，不再硬编码 provider）
    harness.handle('models/autochain', async (args) => {
      const llmSvc = ctx.get('llm');
      const adm = ctx.get('agentDefaultModel');
      try {
        // F8（配置卫生）：noCache 旁路 TTL——「恢复默认」始终取最新自适应链
        const chain = await resolveAdaptiveChain(llmSvc, adm, !!(args && args.noCache === true));
        return { ok: true, chain };
      } catch (e) {
        herr('[enhance] models/autochain failed', e);
        return { ok: false, code: 'AUTOCHAIN_FAILED', message: String(e && e.message ? e.message : e) };
      }
    });

    harness.handle('models/test', async (args) => {
      const provider = args && typeof args.provider === 'string' ? args.provider : '';
      const model = args && typeof args.model === 'string' ? args.model : '';
      const reasoningEffort = args && typeof args.reasoningEffort === 'string' && args.reasoningEffort !== '' ? args.reasoningEffort : undefined;
      const inputChars = args && typeof args.inputChars === 'number' && Number.isFinite(args.inputChars) ? args.inputChars : 0;
      const llmService = ctx.get('llm');
      if (!llmService || typeof llmService.stream !== 'function') {
        return { ok: false, code: 'NO_LLM', message: 'llm service unavailable' };
      }
      if (!provider || !model) return { ok: false, code: 'BAD_ARGS', message: 'provider and model required' };
      const entry = { provider, model, ...(reasoningEffort ? { reasoningEffort } : {}) };
      // 预校验：失败不阻断（目录 advisory，端点最终裁决；结果附 precheck 供展示）
      let precheck = null;
      if (llmService.resolveCallConfig) {
        try {
          await llmService.resolveCallConfig({ provider, model, ...(reasoningEffort ? { reasoningEffort } : {}), maxTokens: 1 });
        } catch (e) {
          precheck = { code: e && e.code ? String(e.code) : 'PRECHECK_FAILED', message: String(e && e.message ? e.message : e) };
        }
      }
      const ref = { current: null };
      let timedOut = false;
      // v3.1.7（方案 2）：探测改长文（~1200 token）后，真实吞吐 75–267 tok/s 需 4–16s + TTFT；
      // 15s 超时不够，放宽到 30s（最慢档 75 tok/s × 1200 token ≈ 16s，留足余量）。
      const timer = ctx.timer.timeout(() => {
        timedOut = true;
        if (ref.current && typeof ref.current.return === 'function') {
          try { ref.current.return(); } catch (e) { /* 忽略 */ }
        }
      }, 30000);
      let r;
      try {
        r = await pingStream(llmService, entry, ref);
      } finally {
        timer();
      }
      if (timedOut) {
        hlog('[enhance] test provider=' + provider + ' model=' + model + (reasoningEffort ? ' effort=' + reasoningEffort : '') + ' → timeout');
        return { ok: false, code: 'TIMEOUT', message: friendlyMessage({ code: 'TIMEOUT' }) };
      }
      hlog('[enhance] test provider=' + provider + ' model=' + model + (reasoningEffort ? ' effort=' + reasoningEffort : '') + ' → ' + (r.ok ? 'ok ' + r.latencyMs + 'ms' : r.code));
      if (r.ok && typeof r.tokensPerSecond === 'number' && Number.isFinite(r.tokensPerSecond) && typeof r.ttftMs === 'number' && Number.isFinite(r.ttftMs)) {
        r.estimatedBaseSeconds = estimateBaseModeSeconds(r.ttftMs, r.tokensPerSecond, inputChars);
        r.estimatedLiteSeconds = estimateLiteModeSeconds(r.ttftMs, r.tokensPerSecond, inputChars);
      }
      return { ...r, ...(precheck && r.ok ? { precheck } : {}) };
    });


    // 2026-08-17（连通性测试预计耗时）：按模型名实时聚合 DSH 会话投影统计。
    // 性能约束：持久化会话全量日志读取很重，不能每次/每个会话都 readSession。
    // 策略：live 会话每次走内存（快）；persisted 会话首次最多扫描 SCAN_LIMIT 个，
    // 命中后把 model route + projection 缓存，后续调用只聚合缓存，避免卡 UI。
    // 匹配口径：只按模型名匹配（用户要求），不区分 provider 路由。
    const sessionModelCache = new Map();        // sid -> { route, at }
    const sessionProjectionCache = new Map();   // sid -> { values, at }
    const SESSION_MODEL_TTL_MS = 600000;        // persisted route 缓存 10 分钟
    const SESSION_PROJECTION_TTL_MS = 600000;   // persisted projection 缓存 10 分钟
    const MODEL_STATS_SCAN_LIMIT = 5;           // 单次调用最多新读多少个 persisted 会话（5 个足够命中同模型历史，避免冷启动超时）

    function cachedSessionModel(sid) {
      const hit = sessionModelCache.get(sid);
      if (hit && Date.now() - hit.at < SESSION_MODEL_TTL_MS) return hit.route;
      return undefined;
    }

    async function loadPersistedSession(sq, proj, sid) {
      const snap = await sq.readSession(sid);
      const route = extractModelRouteFromEvents(snap && snap.events);
      sessionModelCache.set(sid, { route, at: Date.now() });
      let projection = null;
      try {
        const sessionLike = { seq: (snap.events || []).length, events: snap.events || [] };
        const pval = proj.snapshot(sessionLike);
        projection = pval && pval.values ? pval.values : {};
        sessionProjectionCache.set(sid, { values: projection, at: Date.now() });
      } catch (e) {
        projection = null;
      }
      return { route, projection };
    }

    async function resolveModelStats(provider, model) {
      const sq = ctx.get('sessionQuery');
      const proj = ctx.get('sessionProjections');
      if (!sq || typeof sq.listSessions !== 'function' || !proj || typeof proj.snapshot !== 'function') {
        return { ok: false, code: 'NO_STATS', message: 'session stats unavailable' };
      }
      const acc = { ttftMs: 0, ttftSteps: 0, decodeMs: 0, decodeTokens: 0, sessions: 0 };
      try {
        const records = await sq.listSessions();
        let scanBudget = MODEL_STATS_SCAN_LIMIT;
        for (const rec of records) {
          const sid = rec && rec.header && rec.header.id;
          if (!sid) continue;
          let route;
          let projection;
          if (rec.live === true) {
            // live 会话：直接走内存 Session，不落持久化缓存
            const sessions = ctx.get('sessions');
            const live = sessions && typeof sessions.get === 'function' ? sessions.get(sid) : undefined;
            if (!live) continue;
            route = extractModelRouteFromEvents(live.events);
            try {
              const pval = proj.snapshot(live);
              projection = pval && pval.values ? pval.values : {};
            } catch (e) {
              projection = null;
            }
          } else {
            const cachedRoute = cachedSessionModel(sid);
            if (cachedRoute !== undefined) {
              route = cachedRoute;
              const pc = sessionProjectionCache.get(sid);
              if (pc && Date.now() - pc.at < SESSION_PROJECTION_TTL_MS) projection = pc.values;
            } else if (scanBudget > 0) {
              scanBudget -= 1;
              try {
                const loaded = await loadPersistedSession(sq, proj, sid);
                route = loaded.route;
                projection = loaded.projection;
              } catch (e) {
                route = null;
                projection = null;
              }
            }
          }
          if (!route || route.model !== model) continue;
          if (projection) {
            // 按用户要求：只按模型名匹配，不区分 provider 路由
            accumulateProjectionStats(acc, { values: projection });
          }
        }
      } catch (e) {
        herr('[enhance] models/stats failed', e);
        return { ok: false, code: 'STATS_FAILED', message: String(e && e.message ? e.message : e) };
      }
      return { ok: true, ...summarizeModelStats(acc) };
    }

    harness.handle('models/stats', async (args) => {
      const provider = args && typeof args.provider === 'string' ? args.provider : '';
      const model = args && typeof args.model === 'string' ? args.model : '';
      const inputChars = args && typeof args.inputChars === 'number' && Number.isFinite(args.inputChars) ? args.inputChars : 0;
      if (!provider || !model) return { ok: false, code: 'BAD_ARGS', message: 'provider and model required' };
      const stats = await resolveModelStats(provider, model);
      if (!stats.ok) return stats;
      const estimatedBaseSeconds = estimateBaseModeSeconds(stats.ttftMs, stats.tokensPerSecond, inputChars);
      const estimatedLiteSeconds = estimateLiteModeSeconds(stats.ttftMs, stats.tokensPerSecond, inputChars);
      return { ...stats, estimatedBaseSeconds, estimatedLiteSeconds };
    });


    harness.handle('logs/last', async () => ({ ok: true, lines: LOG_RING.slice() }));

    // v2.4.7（每模式独立自定义模板）：返回各模式默认提示词——client 首次切换
    // 「自定义模板」且当前模式无内容时预填用（client 侧无内置模板文本，须 host 提供）。
    // v2.8.0（实测修正）：补 publish 键 = SYSTEM_PUBLISH_PROMPT——此前只返回 4 模式，
    // publish 切自定义模板预填拿到 undefined → 内容为空（用户实测反馈）。
    // 当前 5 模式 base/lite/standard/smart 同值 = SYSTEM_PROMPT；若未来内置按模式拆分
    // （prompts/system-<mode>.md），此 RPC 返回随生成区自动变化，client 无需改动。
    harness.handle('template/default', async () => ({
      ok: true,
      // 兼容保留：defaults[mode] = T1（现有默认模板，行为不变）
      defaults: {
        // v3.1.8（用户指令·每模式默认模板按场景定制）：T1 默认指向模式专属模板
        base: SYSTEM_PROMPT,
        lite: SYSTEM_LITE_PROMPT,
        standard: SYSTEM_STANDARD_PROMPT,
        smart: SYSTEM_SMART_PROMPT,
        publish: SYSTEM_PUBLISH_PROMPT,
      },
      // 模板体系扩展（2026-08-18 修订）：catalog[mode] = [T1, T2]——每模式 2 个内置模板，
      // 供 client 模板选择下拉与新建自定义模板预填（T2=增量模板·保守补充未说的大逻辑/信息，每模式方向不同）
      catalog: {
        base: [SYSTEM_PROMPT, SYSTEM_INCREMENT_PROMPT],
        lite: [SYSTEM_LITE_PROMPT, SYSTEM_INCREMENT_LITE_PROMPT],
        standard: [SYSTEM_STANDARD_PROMPT, SYSTEM_INCREMENT_STANDARD_PROMPT],
        smart: [SYSTEM_SMART_PROMPT, SYSTEM_INCREMENT_SMART_PROMPT],
        publish: [SYSTEM_PUBLISH_PROMPT, SYSTEM_INCREMENT_PUBLISH_PROMPT],
      },
    }));

    // ================= v2.4.0 版本检测与一键更新 RPC =================
    // 方案「插件版本检测与一键更新方案.md」§3：检测（update/check）→ 一键拉取（update/pull）。
    // v2.4.1（实测回填 §9-T5/T6）架构：**host 不再出网**——本部署 web.fetch 无可用 provider
    // （实机抛 WEB_PROVIDER_UNAVAILABLE）；改由 client 浏览器直连 GitHub API（CORS 实测 200），
    // host 只做解析/校验/比较/写入（能力均已实机验证可用）。
    const updateCache = new Map();      // repo → { at, value }（TTL UPDATE_CACHE_TTL_MS）
    const pullInFlight = new Set();     // repo → 拉取中（防重入 PULL_BUSY）

    // v2.4.1（实测回填 §9-T5）：策略必须**带会话解析**——无会话时 workspaceRoot 回退到 DSH
    // 安装目录且写工作区返回 FS_SANDBOX_DENIED（实机验证）；带 session 后 mode=会话预设
    // （如 danger-full-access）、root=会话工作区（实机验证写 ok）。
    function resolveSessionPolicy(sessionId) {
      const sp = ctx.get('sandboxPolicy');
      if (!sp || typeof sp.resolve !== 'function') return null;
      let session;
      try {
        const ss = ctx.get('sessions');
        if (ss && typeof ss.get === 'function' && typeof sessionId === 'string' && sessionId) {
          session = ss.get(sessionId) || undefined;
        }
      } catch (e) { /* 会话解析失败 → 回退无会话策略 */ }
      try {
        return sp.resolve(session ? { session } : undefined);
      } catch (e) {
        return null;
      }
    }


    // v2.6.0：update/apply 与 update/restart 已移除——更新执行迁至独立执行器
    // （lib/updater-host.cjs，127.0.0.1:EXECUTOR_PORT；client 经 update/executorEnsure
    // 获取执行器地址后直连）。原因：重启/重试必须脱离 dsh-web 进程（服务停 = host 死，
    // 依赖 host 的重试必然无法送达——v2.5.5 out.log 无 update/restart 日志为证）。

    // ================= M2 深化：增强管道（bundle 内 Pipeline，契约同已退役的 M2 骨架（P1b 2026-09-19））=================
    // 新增增强模式 / 检索源 = registerEnhanceStage 注册 stage handler，而非修改 enhance 主流程。
    // 2026-08-18（模板体系修订）：每模式 2 个内置模板（default/increment）+ 多自定义模板——
    // system 组装改走 pure.js resolveTemplateSystem（pick/custom 解析 + 旧配置兼容迁移）。
    const enhancePipelineHandlers = new Map();
    function registerEnhanceStage(name, handler, options) {
      const priority = options && Number.isInteger(options.priority) ? options.priority : 0;
      const list = enhancePipelineHandlers.get(name) || [];
      list.push({ handler, priority });
      list.sort((a, b) => a.priority - b.priority);
      enhancePipelineHandlers.set(name, list);
    }
    async function runEnhanceStages(name, value) {
      const list = enhancePipelineHandlers.get(name) || [];
      let v = value;
      for (const { handler } of list) {
        v = await handler(v);
      }
      return v;
    }

    // v2.3（§7.3）：优化进度轮询 RPC——从 pending Map 读 stage（纯展示，失败静默降级）
    harness.handle('enhance/progress', async (args) => {
      const sessionId = args && typeof args.sessionId === 'string' ? args.sessionId : '';
      const seq = args && typeof args.seq === 'number' ? args.seq : -1;
      const rec = pending.get(requestKey(sessionId, seq));
      if (!rec) return { ok: false, code: 'NO_RECORD' };
      // v3.0r（细粒度进度反馈）：返回 stage + 子步骤详情 + 已用时间（纯展示，失败静默降级）
      return {
        ok: true,
        stage: rec.stage || STAGE_PREPARE,
        detailKey: rec.detailKey || '',
        detailArgs: rec.detailArgs || null,
        step: rec.step || 0,
        total: rec.total || 0,
        elapsedMs: rec.startedAt ? Date.now() - rec.startedAt : 0,
        // P0-d：降级清单（辅助调用失败 → 结果在「半瞎」状态生成，用户须可见）
        degraded: Array.isArray(rec.degraded) ? rec.degraded.slice() : [],
        // 复审 medium ⑦ 的配套：重试与降级分通道——重试次数单独暴露（可观测），
        // 混进 degraded 会把「重试后成功」误标成「部分上下文不可用」。
        retries: Array.isArray(rec.retries) ? rec.retries.slice() : [],
      };
    });

    // P0-d（2026-10-12 · 让降级可见）：辅助调用失败此前只写 hlog（环形日志），用户侧零痕迹 ⇒
    // 用户不知道增强结果是在「半瞎」状态下生成的。此处把每次降级登记到 rec.degraded（去重、可枚举），
    // 经 enhance/progress 暴露给 UI，并随最终 result 一并回传（结果态可见）。
    function markDegraded(state, kind) {
      if (!state || !state.rec) return;
      const rec = state.rec;
      if (!Array.isArray(rec.degraded)) rec.degraded = [];
      const k = String(kind || 'unknown');
      if (rec.degraded.indexOf(k) === -1) rec.degraded.push(k);
    }

    // P0-a（2026-10-12 · 补退避重试）：取官方**已解析**的重试策略——按主机文要求**不得硬编码**退避参数，
    // 必须调 ctx.llm.providerRetryPolicy(provider) 取官方解析好的策略再执行（可重试码集同样从策略取）。
    // 旧宿主/未注册路由/服务缺该 API → 返回 null（调用方不重试，行为回到「只尝试一次」）。
    function retryPolicyFor(provider) {
      if (llm === undefined || typeof llm.providerRetryPolicy !== 'function') return null;
      try {
        const pol = llm.providerRetryPolicy(provider);
        return pol && typeof pol === 'object' ? pol : null;
      } catch (e) {
        hlog('[enhance] providerRetryPolicy failed provider=' + provider + ' ' + (e && e.message ? e.message : e));
        return null;
      }
    }

    // P0-a：`always` 模式下官方策略无 maxRetries（不设限）——插件侧安全上限，防无限制组合下不收敛。
    const RETRY_ALWAYS_SAFETY_CAP = 5;

    // P0-a：可中断退避睡眠（经 ctx.timer，宿主销毁即随 fiber 释放；不用裸 setTimeout）。
    // 0/负延迟 → 立即返回；timer 服务异常 → 退化为不等待（重试仍会进行，不会挂死）。
    async function sleepMs(ms) {
      const d = Number(ms);
      if (!Number.isFinite(d) || d <= 0) return;
      try {
        // ctx.timer.timeout(callback, delay)：回调式 API（disposer 返回），包成 Promise 等待一次。
        await new Promise((resolve) => {
          try {
            ctx.timer.timeout(() => resolve(), d);
          } catch (e) { resolve(); }
        });
      } catch (e) { /* 上下文销毁 → 直接继续（由 rec.cancelled/timedOut 兜底） */ }
    }

    // P0-b（2026-10-12 · 辅助调用并入同一预算）：返回距主预算还余多少毫秒；未设预算 → Infinity。
    // 调用点据此把各辅助调用自己的 10–15s 超时**钳到剩余预算内**，并使预算耗尽时直接跳过
    // （记录降级，不阻断主流程）——准备阶段由此纳入主预算，而非各自为政。
    function remainingBudgetMs(state) {
      const dl = state && typeof state.budgetDeadline === 'number' ? state.budgetDeadline : null;
      if (dl === null) return Infinity;
      return Math.max(0, dl - Date.now());
    }
    function helperTimeoutMs(state, baseMs) {
      const remain = remainingBudgetMs(state);
      if (remain === Infinity) return baseMs;
      return Math.max(0, Math.min(baseMs, remain));
    }
    // 预算是否已耗尽（辅助调用直接跳过 + 记降级）
    function budgetExhausted(state) {
      return remainingBudgetMs(state) <= 0;
    }

    // P0-b 修正（2026-10-12 · 独立复核 blocker）：辅助调用超时必须**真正中断其流**。
    // 原实现只把 timedOut 置 true，而 `await collectStream(iterator, …)` 会一直等到流自己结束
    // ⇒ 慢但健康的辅助会跑过自己的钳后超时（实测 20s 钳制下仍跑到 23–24s），
    // 从而越过 prepareBudgetMs 侵蚀 genTimeoutMs —— 复现实测：辅助 23s/24s 时生成 genCalls=0、
    // 整体 TIMEOUT（HEAD 同场景 ok:true）——正是 P0-b 自述要防的「拆东墙」。
    // 现改为：超时到点即 `iterator.return()` 中止流 + **立即以超时结算**（绝不等待流自然结束）。
    // 实现为一个可 race 的「超时闸」：闸开 → 中止迭代器 + 以 {kind:'aborted'} 结算。
    // 返回 { timedOut(), attach(iterator), race(collectPromise), dispose() }。
    function startHelperAbort(state, baseMs) {
      const ms = helperTimeoutMs(state, baseMs);
      let fired = false;
      let iterator = null;
      let fireTimer = null;
      let settle = null;
      const abortIterator = () => {
        // 真中断：迭代器 return()（官方 AsyncIterable 契约）——底层适配器随即停止产出
        if (iterator && typeof iterator.return === 'function') {
          try { iterator.return(); } catch (e) { /* 忽略 */ }
        }
      };
      // 超时闸：到点 → 置标志 + 中止流 + 让 race 以 aborted 结算（不再等流自然结束）
      const gate = new Promise((resolve) => { settle = resolve; });
      if (ms > 0) {
        fireTimer = ctx.timer.timeout(() => {
          fired = true;
          abortIterator();
          try { settle({ kind: 'aborted', aborted: true }); } catch (e) { /* 忽略 */ }
        }, ms);
      } else {
        // 预算已耗尽 → 立即超时（调用点会据此跳过并记降级）
        fired = true;
        try { settle({ kind: 'aborted', aborted: true }); } catch (e) { /* 忽略 */ }
      }
      return {
        timedOut: () => fired,
        attach: (it) => { iterator = it; if (fired) abortIterator(); },
        race: (collectPromise) => Promise.race([collectPromise, gate]),
        dispose: () => { try { if (fireTimer) fireTimer(); } catch (e) { /* 忽略 */ } abortIterator(); },
      };
    }

    // v3.0r（细粒度进度反馈）：写进度详情（stage/detailKey/detailArgs/step/total）
    function setProgress(rec, stage, key, args, step, total) {
      rec.stage = stage;
      rec.detailKey = key || '';
      rec.detailArgs = args || null;
      rec.step = step || 0;
      rec.total = total || 0;
    }

    // ---- stage: analyze——配置解析 / 模型链 / system 组装 / 记忆与场景准备 ----
    async function enhanceStageAnalyze(state) {
      const args = state.args;
      const sessionId = state.sessionId;
      const text = state.text;
      // 2026-08-18（用户需求·每模式步骤补充）：analyze 阶段开始即上报进度「分析任务」
      if (state.rec) setProgress(state.rec, STAGE_ANALYZE);
      const cfg = validateConfig(args && args.config);
      // v2.1（§2.2）：client 已判定实际模式（显式/auto/seed），请求 mode 覆盖解析值
      if (args && typeof args.mode === 'string' && MODE_KEYS.includes(args.mode)) cfg.mode = args.mode;
      // v2.8.2 曾一键发布记忆强制开启；2026-08-18（用户指令）取消——记忆跟随开关，publish 不例外
      // v23（D6）：模型链 = cfg.fallback 按序（每条独立 reasoningEffort）；
      // 2026-08-18（用户需求·删内置兜底链）：完全按用户配置顺序——链为空 → 空链（不自适应/BUILTIN 补足），llm 阶段报无模型
      const chain = buildTryChain(cfg.fallback);
      // 模板体系扩展（2026-08-18 修订）：每模式 2 个内置模板（default=默认模板·只清晰化重述 /
      // increment=增量模板·保守补充未说的大逻辑/信息，每模式方向不同）+ 每模式多自定义模板
      // （pick=custom:<index>）；解析见 pure.js resolveTemplateSystem——旧配置（无 pick）自动迁移
      // （custom+texts 非空仍生效），行为与旧版等价；旧内置键 supplement/dev 按 increment 处理；非法选中回退 T1。
      // v2.7.0（一键发布）：publish 模式内置专用九章规格 system（custom 模板仍可覆盖）
      // v3.2.23（提示词集合化）：模式→模板映射由 SKILL_MANIFEST 驱动（prompts/enhance/*/PACKAGE.md frontmatter 声明）
      const BUILTIN_TEMPLATES = {};
      for (const _m of Object.keys(SKILL_MANIFEST)) {
        BUILTIN_TEMPLATES[_m] = [SKILL_MANIFEST[_m].templates.t1, SKILL_MANIFEST[_m].templates.t2];
      }
      let system = resolveTemplateSystem(cfg, cfg.mode, BUILTIN_TEMPLATES);
      // v3.2.19（用户需求·纪律约束模板）：输出纪律无条件追加——所有模式（含自定义模板）
      // 都必带，从源头约束「只输出优化后的提示词本体」（与 cleanOutput 事后清理互补）
      system = system + '\n\n' + DISCIPLINE_PROMPT;
      // v3.0（模式重构）：lite 规则检查移除——lite 改为「前 1 轮会话关联参考」（见 retrieve stage）
      // v2.6.1（记忆链）：rounds 数组（时间序 [{input,output}]，≤MEMORY_ROUNDS_MAX 轮）→
      // 真多轮消息注入；hasMemory = rounds 非空；开关关 / 预算 0 → 不注入（行为不变）。
      const memRounds = args && args.memory && Array.isArray(args.memory.rounds)
        ? args.memory.rounds.filter((r) => r && (r.input || r.output)).slice(-MEMORY_ROUNDS_MAX)
        : [];
      const hasMemory = memRounds.length > 0;
      const memoryActive = shouldInjectMemory(cfg.memory, hasMemory, cfg.context.budgetChars);
      // v2.7.0（一键发布 · 改动方向代入检索）：delta 提前计算（记忆链轮次时），
      // 供 publish 网络检索词构造（buildWebQuery）使用；无记忆链 → null（检索词仅主题词）
      // v2.8.0（实测修正）：publish 的 removed 侧清零（补充式输入下 removed=上一轮规格，
      // 污染检索词并误导模型——见 filterDeltaForPublish）；hint 与检索词均用过滤后 delta
      let memDelta = null;
      if (memoryActive) {
        const lastOutput = memRounds[memRounds.length - 1].output;
        memDelta = filterDeltaForPublish(computeEditDelta(lastOutput, text), cfg.mode);
      }
      // v2.8.0（一键发布 · 场景路由）：publish 场景判定——会话级缓存固定（首轮判定写入、
      // 后续轮读取不重判）。判定源：缓存 miss 且记忆链非空 → 最早轮输入（进程重启续作兜底，
      // 判定源与注入轮次同源，避免增量文本导致场景翻转）；无记忆链 → 当轮 text。
      // 判定+写入在 system 注入前完成，与 LLM 调用成败无关（scenario 仅依赖判定源）。
      let scenario = 'generic';
      if (cfg.mode === 'publish') {
        const cached = publishScenarioCache.get(sessionId);
        if (cached) {
          scenario = cached;
        } else {
          const src = memRounds.length > 0 ? memRounds[0].input : text;
          scenario = detectScenario(src);
          publishScenarioCache.set(sessionId, scenario);
        }
        if (scenario !== 'generic') {
          system = system + '\n\n【场景判定】本次场景判定：' + scenario + '（依据用户输入自动判定；章节适配要求见「场景适配」段；请勿复述本判定行）';
        }
        hlog('[enhance] scenario=' + scenario + (cached ? ' cached' : ' judged src=' + (memRounds.length > 0 ? 'rounds[0]' : 'text')));
      }
      // v2.7.0（publish 一键发布）：规格长文生成不设限制——maxTokens 省略（provider 默认上限）、
      // outputLimit=0（collectStream 不截断）、超时放宽至 ≥120s（长文生成耗时）
      // v2.8.0（实测修正）：120s → 240s——带记忆链 rounds 的多轮规格生成（重负载路径）
      // 实测 120s 超时（round-2 完整九章 + 融入补充 + 自评），240s 覆盖 4 轮链最坏情况
      const isPublish = cfg.mode === 'publish';
      state.cfg = cfg;
      state.chain = chain;
      state.system = system;
      state.memRounds = memRounds;
      state.hasMemory = hasMemory;
      state.memoryActive = memoryActive;
      state.memDelta = memDelta;
      state.isContinuation = memoryActive && memRounds.length > 0 && memDelta !== null && (memDelta.added.length > 0 || memDelta.removed.length > 0);
      state.scenario = scenario;
      state.isPublish = isPublish;
      // v3.0p 审查（超时/耗时匹配）：链含 effort 时超时自动放宽 ≥120s——实测 effort=max 长草稿
      // （1500 字）完整生成 42s > 默认 30s → 必超时；无 effort 行为不变
      // v2.7.0 曾 publish 强制超时 ≥240s / maxTokens=0 / outputLimit=0（规格长文不截断）；
      // 2026-08-18（用户指令）取消强制——publish 三项参数可调（默认档 60s/4k/16k 按实测覆盖）
      // v3.1.7（用户需求·超时无限制）：cfg.timeoutMs=0（无限制）不被 effort 放宽覆盖——保持 0 不挂超时
      // P0-b（2026-10-12 · 单一事实源）：公式抽出为 resolveEnhanceTimeoutMs（pure.js），
      // 与 enhance handler 在准备阶段之前挂计时器时用的是**同一个函数**——杜绝两处漂移。
      state.timeoutMs = resolveEnhanceTimeoutMs(cfg, chain);
      state.maxTokens = cfg.maxTokens;
      state.outputLimit = cfg.outputLimit;
      return state;
    }

    // ---- stage: retrieve——V2 上下文构建 / 检索 ----
    // ---- v3.0：会话历史提取（listEvents/filterEvents → extractHistory；失败/不可用 → []）----
    async function fetchSessionHistory(sessionId, state) {
      const sq = ctx.get('sessionQuery');
      if (!sq || typeof sq.listEvents !== 'function' || typeof sq.filterEvents !== 'function') return [];
      // v3.0p 审查（超时/耗时匹配）：会话历史提取补超时保护（10s，超时/失败 → [] 不阻断）
      // P0-b 修正（2026-10-12 · 第三轮 · 独立复核 blocker）：原先 histTimer **只置标志位**，
      // 而 `await sq.readSurface(...)` / `await sq.listEvents(...)` 会一直等到调用自己返回
      // ⇒ 慢的会话读取可越过钳后超时、吃掉总预算并侵蚀生成额度（复核实测：readSurface 23s/24s/30s
      // ⇒ 改后 TIMEOUT、genCalls=0，HEAD 为 ok:true）。
      // 现统一到 startWaitAbort（race + dispose，机制与 LLM 腿的 startHelperAbort 同源）：
      // 超时即**不再等待**该调用，并按上游「超时 → 跳过检索段」语义返回 []，同时登记降级。
      const waitAbort = startWaitAbort(ctx.timer, V2_SEARCH_EVENTS_TIMEOUT_MS);
      try {
        // v3.1.3（用户需求·仅结论参考）：优先 readSurface（完整事件，保留 content 块结构）
        // → 结论提取（仅 text 块，丢弃思考/工具调用/系统注入）；旧 listEvents+filterEvents
        // 路径的文档文本为预拼接语义文本（含工具参数），仅作 readSurface 缺失时的兜底。
        if (typeof sq.readSurface === 'function') {
          const surface = await waitAbort.race(sq.readSurface(sessionId));
          if (waitAbort.timedOut()) { markDegraded(state, 'history-timeout'); hlog('[enhance] v3 history timeout'); return []; }
          const events = extractHistoryConclusions(surface && surface.events);
          hlog('[enhance] v3 history events=' + events.length + ' conclusion-only');
          return events;
        }
        const records = await waitAbort.race(sq.listEvents(sessionId));
        if (waitAbort.timedOut()) { markDegraded(state, 'history-timeout'); hlog('[enhance] v3 history timeout'); return []; }
        const msgSeqs = [];
        for (let i = records.length - 1; i >= 0 && msgSeqs.length < V2_MSG_SEQ_SCAN; i--) {
          const r = records[i];
          const t = String(r && r.type || '');
          if (t === 'user/message' || t === 'assistant/message') msgSeqs.push(r && r.seq);
        }
        if (msgSeqs.length === 0) return [];
        const minSeq = msgSeqs[msgSeqs.length - 1];
        const docs = await waitAbort.race(sq.filterEvents(sessionId, [{ kind: 'seq', from: minSeq }]));
        if (waitAbort.timedOut()) { markDegraded(state, 'history-timeout'); hlog('[enhance] v3 history timeout'); return []; }
        const events = extractHistory(docs, V2_HISTORY_LIMIT);
        hlog('[enhance] v3 history events=' + events.length);
        return events;
      } catch (e) {
        hlog('[enhance] v3 history failed', e && e.message ? e.message : e);
        return [];
      } finally {
        waitAbort.dispose();
      }
    }

    // ---- v3.0：LLM 关联性判定（RELEVANCE_PROMPT 占位替换；10s 超时；失败/解析失败 → 不相关）----
    async function judgeRelevance(historyText, currentText, entry, state) {
      if (llm === undefined || !entry) { markDegraded(state, 'relevance'); return { related: false, reason: 'no-llm' }; }
      // P0-b：辅助调用并入主预算——超预算直接跳过（记降级，不阻断主流程）
      if (budgetExhausted(state)) { markDegraded(state, 'relevance-budget'); hlog('[enhance] v3 relevance skipped budget-exhausted'); return { related: false, reason: 'budget-exhausted' }; }
      const system = RELEVANCE_PROMPT
        .replace('{history}', String(historyText || ''))
        .replace('{current}', String(currentText || ''));
      let timedOut = false;
      // P0-b：自身 10s 超时钳到剩余预算内（不越过主预算）
      // P0-b 修正：超时到点**真正中止**该辅助流（不再等它自然结束——见 startHelperAbort 注释）
      const abortCtl = startHelperAbort(state, RELEVANCE_TIMEOUT_MS);
      try {
        const stream = llm.stream({
          provider: entry.provider,
          model: entry.model,
          // v3.0p 审查（超时/耗时匹配）：judge 类小调用剥离 reasoningEffort——判定/规划任务无需深度思考；effort 思考会消耗小预算输出（空流风险）并放大耗时
          maxTokens: RELEVANCE_MAX_TOKENS,
          system,
          messages: [{
            id: 'enhance-relevance',
            role: 'user',
            content: [{ type: 'text', text: '请依据上述规则判断关联性。' }],
            source: { kind: 'user' },
          }],
        });
        const iterator = stream[Symbol.asyncIterator]();
        abortCtl.attach(iterator);
        const collectP = collectStream(iterator, RELEVANCE_OUTPUT_LIMIT);
        // 超时闸先结算时，collectP 可能随后才 reject —— 先挂空处理器，避免未处理拒绝
        collectP.catch(() => { /* 落败方 */ });
        const result = await abortCtl.race(collectP);
        timedOut = abortCtl.timedOut();
        // P0-e（消费点 2/6 之一）：max-tokens 现返回可区分 kind 'maxtokens'（不再是 EMPTY_RESPONSE）；
        // 判定类辅助调用**按原样透传**——非 'ok' 一律判失败（显式声明，不静默沿用旧兜底）。
        if (!timedOut && result.kind === 'ok') {
          const parsed = parseRelevance(result.text);
          if (parsed) return parsed;
        }
        // P0-d：判定失败/超时 → 记降级（结果在无参考状态下生成，用户须可见）
        markDegraded(state, timedOut ? 'relevance-timeout' : (result.kind === 'maxtokens' ? 'relevance-truncated' : 'relevance-unparsed'));
        hlog('[enhance] v3 relevance ' + (timedOut ? 'timeout' : 'unparsed'));
      } catch (e) {
        markDegraded(state, 'relevance-failed');
        hlog('[enhance] v3 relevance failed', e && e.message ? e.message : e);
      } finally {
        abortCtl.dispose();
      }
      return { related: false, reason: 'judge-failed' };
    }


    // ---- v3.0p（publish 多步检索）：LLM 检索主题规划（WEBSEARCH_PLAN_PROMPT 占位替换；
    // 10s 超时；失败/解析失败 → null → retrieve 降级 buildWebQuery 单 query）----
    async function planWebSearch(text, memoText, scenario, entry, state) {
      if (llm === undefined || !entry) { markDegraded(state, 'webplan'); return null; }
      // P0-b：辅助调用并入主预算——超预算直接跳过（降级为单 query 路径）
      if (budgetExhausted(state)) { markDegraded(state, 'webplan-budget'); hlog('[enhance] v3p web-plan skipped budget-exhausted'); return null; }
      const system = WEBSEARCH_PLAN_PROMPT
        .replace('{text}', String(text || ''))
        .replace('{memo}', String(memoText || '（暂无）'))
        .replace('{scenario}', String(scenario || 'generic'));
      let timedOut = false;
      // P0-b 修正：超时到点**真正中止**该辅助流（不再等它自然结束——见 startHelperAbort 注释）
      const abortCtl = startHelperAbort(state, WEB_PLAN_TIMEOUT_MS);
      try {
        const stream = llm.stream({
          provider: entry.provider,
          model: entry.model,
          // v3.0p 审查（超时/耗时匹配）：judge 类小调用剥离 reasoningEffort——判定/规划任务无需深度思考；effort 思考会消耗小预算输出（空流风险）并放大耗时
          maxTokens: WEB_PLAN_MAX_TOKENS,
          system,
          messages: [{
            id: 'enhance-webplan',
            role: 'user',
            content: [{ type: 'text', text: '请输出检索主题规划。' }],
            source: { kind: 'user' },
          }],
        });
        const iterator = stream[Symbol.asyncIterator]();
        abortCtl.attach(iterator);
        const collectP = collectStream(iterator, WEB_PLAN_OUTPUT_LIMIT);
        // 超时闸先结算时，collectP 可能随后才 reject —— 先挂空处理器，避免未处理拒绝
        collectP.catch(() => { /* 落败方 */ });
        const result = await abortCtl.race(collectP);
        timedOut = abortCtl.timedOut();
        // P0-e（消费点 3/6）：maxtokens 按原样透传 → 非 ok 即降级（显式声明）。
        if (!timedOut && result.kind === 'ok') {
          const parsed = parseSearchPlan(result.text);
          if (parsed) return parsed;
        }
        markDegraded(state, timedOut ? 'webplan-timeout' : (result.kind === 'maxtokens' ? 'webplan-truncated' : 'webplan-unparsed'));
        hlog('[enhance] v3p web-plan ' + (timedOut ? 'timeout' : 'unparsed'));
      } catch (e) {
        markDegraded(state, 'webplan-failed');
        hlog('[enhance] v3p web-plan failed', e && e.message ? e.message : e);
      } finally {
        abortCtl.dispose();
      }
      return null;
    }
    // ---- v3.0（S3）：工作区文件检索（扩展名过滤 + 关键词排序 + 摘要；2s 超时降级）----
    const DOC_FILE_RE = /\.md$/i;
    const CODE_FILE_RE = /\.(?:js|ts|jsx|tsx|py|go|rs|java|cpp|c|h|cs|rb|php|sql|sh|vue|html|css|json|yaml|yml|toml)$/i;
    async function searchWorkspaceFiles(extRe, keywords, maxFiles, maxDepth, paths) {
      const fsSvc = ctx.get('fs');
      const sp = ctx.get('sandboxPolicy');
      const root = sp && sp.workspaceRoot;
      if (!fsSvc || !root || typeof fsSvc.listDir !== 'function' || typeof fsSvc.resolve !== 'function' || typeof fsSvc.readText !== 'function') return [];
      // P0-b 修正（2026-10-12 · 第三轮）：标志位 → race+dispose（与 v2SearchWorkspace 同一机制）。
      // 慢的 fs 调用此前会越过 V2_WORKSPACE_TIMEOUT_MS 一直等 ⇒ 侵蚀生成额度。
      const waitAbort = startWaitAbort(ctx.timer, V2_WORKSPACE_TIMEOUT_MS);
      const aborted = () => waitAbort.timedOut();
      try {
        let rootTarget;
        try { rootTarget = await waitAbort.race(fsSvc.resolve(root)); } catch (e) { return []; }
        if (waitAbort.timedOut()) return [];
        const files = [];
        const walk = async (target, rel, level) => {
          if (aborted() || files.length >= SCAN_FILE_LIST_MAX || level > maxDepth) return;
          let entries;
          try { entries = await waitAbort.race(fsSvc.listDir(target)); } catch (e) { return; }
          if (waitAbort.timedOut()) return;
          for (const en of entries || []) {
            if (aborted()) return;
            const name = en && en.name;
            if (!name) continue;
            if (en.type === 'directory') {
              if (V2_WORKSPACE_IGNORE_DIRS.has(name)) continue;
              const sub = en.target;
              if (sub) await walk(sub, rel ? rel + '/' + name : name, level + 1);
              continue;
            }
            const p = rel ? rel + '/' + name : name;
            if (extRe.test(name) && !shouldIgnoreFile(p)) files.push(p);
          }
        };
        await walk(rootTarget, '', 1);
        const kws = (keywords || []).filter((k) => typeof k === 'string' && k.length >= 2);
        // 关键词为空（短文本提不出词）→ 不排序直接取前 maxFiles；
        // 关键词非空但名称 0 命中 → 内容兜底扫描（中文关键词 vs 英文文件名的老问题，
        // 与 v2SearchWorkspace content-fallback 同策略）
        let ranked = kws.length > 0 ? rankFiles(files, kws, 10).map((c) => c.path) : files.slice(0, maxFiles);
        if (ranked.length === 0 && kws.length > 0) {
          const scored = [];
          // 中文组合词分段匹配（「登录功能」→「登录」/「功能」），避免 4 字组合词 vs 内容子串失配
          const kwSegs = [];
          for (const k of kws) {
            const kl = String(k).toLowerCase();
            kwSegs.push(kl);
            for (const sg of splitCnSegments(kl)) {
              if (sg.length >= 2 && !kwSegs.includes(sg)) kwSegs.push(sg);
            }
            // 2 字前缀兜底（组合词切不开时，如「登录功能」→「登录」）
            if (kl.length >= 2 && !kwSegs.includes(kl.slice(0, 2))) kwSegs.push(kl.slice(0, 2));
          }
          for (const rel of files.slice(0, 8)) {
            if (aborted()) break;
            try {
              const tgt = await waitAbort.race(fsSvc.resolve(rel, { cwd: root }));
              if (waitAbort.timedOut()) break;
              const text = await waitAbort.race(fsSvc.readText(tgt));
              if (waitAbort.timedOut()) break;
              let hits = 0;
              for (const ln of text.split('\n')) {
                if (kwSegs.length > 0 && kwSegs.some((sg) => ln.toLowerCase().includes(sg))) hits++;
                if (hits >= 8) break;
              }
              if (hits > 0) scored.push({ path: rel, hits });
            } catch (e) { /* 跳过 */ }
          }
          scored.sort((a, b) => b.hits - a.hits);
          ranked = scored.slice(0, maxFiles).map((s) => s.path);
        }
        // 最终兜底：内容仍不匹配（中文关键词 vs 英文代码/文件名的语义鸿沟）→ 取前 N 个
        // （开发环境已确认或 md 文档场景下文件有限，全取参考优于空参考）
        if (ranked.length === 0) ranked = files.slice(0, maxFiles);
        // v3.0v2：项目地图指向路径优先（codePaths 前缀命中排前，不足补全量）
        if (paths && paths.length > 0 && files.length > 0) {
          const prefixed = files.filter((f) => paths.some((p) => f === p || f.startsWith(p + '/')));
          const rest = files.filter((f) => !prefixed.includes(f));
          ranked = prefixed.concat(rest).slice(0, maxFiles);
        }
        const out = [];
        for (const rel of ranked.slice(0, maxFiles)) {
          if (aborted()) break;
          try {
            const tgt = await waitAbort.race(fsSvc.resolve(rel, { cwd: root }));
            if (waitAbort.timedOut()) break;
            const text = await waitAbort.race(fsSvc.readText(tgt));
            if (waitAbort.timedOut()) break;
            out.push({ path: rel, snippet: snippetFromLines(text.split('\n'), kws, SNIPPET_BUDGET) });
          } catch (e) { /* 跳过 */ }
        }
        return out;
      } finally {
        waitAbort.dispose();
      }
    }

    // ---- v3.0v2：smart 工作区阶段（门槛：有 .md + 相关文档命中 + 项目地图结构）----
    // 返回 { block, enteredThird }——enteredThird 决定 SMART_TAIL（调整方案）是否追加。
    async function enhanceSmartWorkspace(state, text, chain0, rbudget) {
      // v3.1.8（用户需求·预算真正生效）：smart 工作区规模随预算伸缩（BUDGET_RETRIEVE_TABLE）——
      // 文档扫描数/深度、文档与代码内容上限随档位递增；预算 0 由调用方跳过（不进入本函数）。
      const kws = extractKeywords(text, []);
      const docs = await searchWorkspaceFiles(DOC_FILE_RE, kws, rbudget.smartDocs, rbudget.smartDepth);
      if (docs.length === 0) {
        hlog('[enhance] v3 smart no-md');
        return { block: state.v2Block, enteredThird: false };
      }
      const docsText = docs.map((d) => '📄 ' + d.path + '\n' + d.snippet).join('\n\n').slice(0, rbudget.smartChars);
      // B+C 合并：一次 LLM 调用——检索相关文档 + 分析项目地图结构
      if (state.rec) setProgress(state.rec, STAGE_FILES, 'docs');
      const analysis = await analyzeDocsRelevance(docsText, text, state.v2Block || '', chain0, state);
      if (!analysis || analysis.relatedDocs.length === 0) {
        hlog('[enhance] v3 smart no-related-doc');
        return { block: state.v2Block, enteredThird: false };
      }
      const docPart = (state.v2Block ? state.v2Block + '\n\n' : '') + '【项目文档参考】\n' +
        analysis.relatedDocs.map((d) => '📄 ' + d.path + '\n' + d.excerpt).join('\n\n');
      if (!analysis.hasProjectMap) {
        hlog('[enhance] v3 smart no-project-map reason=' + analysis.reason);
        return { block: docPart, enteredThird: false };
      }
      // 第三步：代码文档检索（项目地图指向路径优先）
      hlog('[enhance] v3 smart project-map paths=' + JSON.stringify(analysis.codePaths));
      if (state.rec) setProgress(state.rec, STAGE_FILES, 'code');
      const codes = await searchWorkspaceFiles(CODE_FILE_RE, kws, 3, 3, analysis.codePaths);
      const codeText = codes.map((c) => '📄 ' + c.path + '\n' + c.snippet).join('\n\n').slice(0, rbudget.smartCodeChars);
      return { block: codeText ? docPart + '\n\n【相关代码参考】\n' + codeText : docPart, enteredThird: true };
    }

    // ---- v3.0v2：提示词开发意向判定（DEV_INTENT_PROMPT；10s 超时降级非开发意向）----
    async function judgeDevIntent(text, sessionRef, entry, state) {
      if (llm === undefined || !entry) { markDegraded(state, 'intent'); return { isDevIntent: false, reason: 'no-llm' }; }
      if (budgetExhausted(state)) { markDegraded(state, 'intent-budget'); hlog('[enhance] v3 intent skipped budget-exhausted'); return { isDevIntent: false, reason: 'budget-exhausted' }; }
      const system = DEV_INTENT_PROMPT
        .replace('{prompt}', String(text || ''))
        .replace('{session}', String(sessionRef || ''));
      let timedOut = false;
      // P0-b 修正：超时到点**真正中止**该辅助流（不再等它自然结束——见 startHelperAbort 注释）
      const abortCtl = startHelperAbort(state, RELEVANCE_TIMEOUT_MS);
      try {
        const stream = llm.stream({
          provider: entry.provider,
          model: entry.model,
          // v3.0p 审查（超时/耗时匹配）：judge 类小调用剥离 reasoningEffort——判定/规划任务无需深度思考；effort 思考会消耗小预算输出（空流风险）并放大耗时
          maxTokens: RELEVANCE_MAX_TOKENS,
          system,
          messages: [{
            id: 'enhance-intent',
            role: 'user',
            content: [{ type: 'text', text: '请依据上述规则判断。' }],
            source: { kind: 'user' },
          }],
        });
        const iterator = stream[Symbol.asyncIterator]();
        abortCtl.attach(iterator);
        const collectP = collectStream(iterator, RELEVANCE_OUTPUT_LIMIT);
        // 超时闸先结算时，collectP 可能随后才 reject —— 先挂空处理器，避免未处理拒绝
        collectP.catch(() => { /* 落败方 */ });
        const result = await abortCtl.race(collectP);
        timedOut = abortCtl.timedOut();
        // P0-e（消费点 4/6）：maxtokens 按原样透传 → 非 ok 即降级（显式声明）。
        if (!timedOut && result.kind === 'ok') {
          const parsed = parseIntent(result.text);
          if (parsed) return parsed;
        }
        markDegraded(state, timedOut ? 'intent-timeout' : (result.kind === 'maxtokens' ? 'intent-truncated' : 'intent-unparsed'));
        hlog('[enhance] v3 intent ' + (timedOut ? 'timeout' : 'unparsed'));
      } catch (e) {
        markDegraded(state, 'intent-failed');
        hlog('[enhance] v3 intent failed', e && e.message ? e.message : e);
      } finally {
        abortCtl.dispose();
      }
      return { isDevIntent: false, reason: 'judge-failed' };
    }

    // ---- v3.0v2：文档检索 + 项目地图合并分析（DOC_ANALYSIS_PROMPT 一次调用）----
    async function analyzeDocsRelevance(docsText, text, sessionRef, entry, state) {
      if (llm === undefined || !entry) { markDegraded(state, 'docs'); return null; }
      if (budgetExhausted(state)) { markDegraded(state, 'docs-budget'); hlog('[enhance] v3 doc-analysis skipped budget-exhausted'); return null; }
      const system = DOC_ANALYSIS_PROMPT
        .replace('{docs}', String(docsText || ''))
        .replace('{prompt}', String(text || ''))
        .replace('{session}', String(sessionRef || ''));
      let timedOut = false;
      // P0-b 修正：超时到点**真正中止**该辅助流（不再等它自然结束——见 startHelperAbort 注释）
      const abortCtl = startHelperAbort(state, RELEVANCE_TIMEOUT_MS);
      try {
        const stream = llm.stream({
          provider: entry.provider,
          model: entry.model,
          // v3.0p 审查（超时/耗时匹配）：judge 类小调用剥离 reasoningEffort——判定/规划任务无需深度思考；effort 思考会消耗小预算输出（空流风险）并放大耗时
          maxTokens: RELEVANCE_MAX_TOKENS,
          system,
          messages: [{
            id: 'enhance-docanalysis',
            role: 'user',
            content: [{ type: 'text', text: '请依据上述规则分析。' }],
            source: { kind: 'user' },
          }],
        });
        const iterator = stream[Symbol.asyncIterator]();
        abortCtl.attach(iterator);
        const collectP = collectStream(iterator, RELEVANCE_OUTPUT_LIMIT);
        // 超时闸先结算时，collectP 可能随后才 reject —— 先挂空处理器，避免未处理拒绝
        collectP.catch(() => { /* 落败方 */ });
        const result = await abortCtl.race(collectP);
        timedOut = abortCtl.timedOut();
        // P0-e（消费点 5/6）：maxtokens 按原样透传 → 非 ok 即降级（显式声明）。
        if (!timedOut && result.kind === 'ok') {
          const parsed = parseDocsAnalysis(result.text);
          if (parsed) return parsed;
        }
        markDegraded(state, timedOut ? 'docs-timeout' : (result.kind === 'maxtokens' ? 'docs-truncated' : 'docs-unparsed'));
        hlog('[enhance] v3 doc-analysis ' + (timedOut ? 'timeout' : 'unparsed'));
      } catch (e) {
        markDegraded(state, 'docs-failed');
        hlog('[enhance] v3 doc-analysis failed', e && e.message ? e.message : e);
      } finally {
        abortCtl.dispose();
      }
      return null;
    }
    // ---- stage: retrieve——v3.0 检索策略分发（rounds 窗口判定 / v2 旧管道 / none）----
    async function enhanceStageRetrieve(state) {
      const cfg = state.cfg;
      const text = state.text;
      const sessionId = state.sessionId;
      const rec = state.rec;
      const row = SKILL_MANIFEST[cfg.mode].retrieve || SKILL_MANIFEST[DEFAULT_MODE].retrieve; // v3.2.23 retrieve 声明化（prompts/*/PACKAGE.md）
      state.v2Block = '';
      state.v2Log = 'none';
      if (state.isContinuation) {
        state.v2Log = 'continuation-skip';
        return state;
      }
      if (row.kind === 'rounds' && row.windows.length > 0) {
        // v3.1.8（用户需求·预算真正生效）：rounds 模式消费上下文预算——budget 0 = 跳过检索
        // （不注入参考，等价 base 直发）；budget > 0 时注入上限随档位伸缩（BUDGET_RETRIEVE_TABLE）。
        const rbudget = resolveRetrieveBudget(cfg.mode, cfg.context && cfg.context.budgetChars ? cfg.context.budgetChars : 0);
        if (rbudget.roundsChars > 0) {
          // v3.0：会话轮次窗口关联检索——逐窗口 LLM 判定，命中即停并注入参考；
          // 窗口越界（历史不足）跳过；全不中 → 无参考（不阻断主流程）。
          // 2026-08-18（用户需求·步骤补充）：rounds 模式补「读取会话」进度（与 publish 一致）
          if (state.rec) setProgress(state.rec, STAGE_HISTORY);
          const events = await fetchSessionHistory(sessionId, state);
          const chain0 = state.chain && state.chain.length > 0 ? state.chain[0] : null;
          for (let wi = 0; wi < row.windows.length; wi++) {
            const win = row.windows[wi];
            if (rec.cancelled || rec.timedOut) break;
            const winText = splitHistoryRounds(events, win[0], win[1]).join('\n');
            if (winText === '') {
              hlog('[enhance] v3 window empty rounds=' + win[0] + '-' + win[1]);
              continue;
            }
            setProgress(rec, STAGE_ANALYZE, 'judge', null, wi + 1, row.windows.length);
            const judge = await judgeRelevance(winText, text, chain0, state);
            if (judge.related) {
              state.v2Block = '【相关会话参考（仅吸收明确需求，禁止复述）】\n' + winText.slice(0, rbudget.roundsChars);
              state.v2Log = 'rounds=' + win[0] + '-' + win[1] + ' chars=' + winText.length + ' inject=' + Math.min(winText.length, rbudget.roundsChars) + ' reason=' + judge.reason;
              hlog('[enhance] v3 window hit rounds=' + win[0] + '-' + win[1] + ' reason=' + judge.reason);
              break;
            }
            hlog('[enhance] v3 window miss rounds=' + win[0] + '-' + win[1] + ' reason=' + judge.reason);
          }
          // v3.0v2：smart——窗口判定后先判开发意向（非开发意向直接停，不进工作区）；
          // 开发意向 → 工作区阶段（.md + 相关文档命中 + 项目地图三门槛），
          // 仅进入第三步（代码阶段）才追加 SMART_TAIL（调整方案输出）
          if (SKILL_MANIFEST[cfg.mode].sources.indexOf('workspace') !== -1) {
            setProgress(rec, STAGE_ANALYZE, 'intent');
            const intent = await judgeDevIntent(text, state.v2Block || '', chain0, state);
            if (!intent.isDevIntent) {
              hlog('[enhance] v3 smart not-dev-intent reason=' + intent.reason);
            } else {
              hlog('[enhance] v3 smart dev-intent reason=' + intent.reason);
              const ws = await enhanceSmartWorkspace(state, text, chain0, rbudget);
              state.v2Block = ws.block;
              if (ws.enteredThird) {
                state.system = state.system + '\n\n' + SMART_TAIL_PROMPT;
                hlog('[enhance] v3 smart tail injected');
              }
            }
          }
        } else {
          // 预算 0：rounds 检索跳过（不注入参考；smart 工作区同样不进入）
          state.v2Log = 'rounds-skip budget=0';
        }
      } else if (row.kind === 'v2') {
        // publish：v2 旧管道 + v3.0p 多步网络检索（LLM 规划主题 → 逐主题搜索 → 跨轮记忆回注）
        const memoRec = publishWebMemo.get(sessionId);
        const memoText = memoRec && memoRec.memo ? memoRec.memo : '';
        const memoTopics = memoRec && Array.isArray(memoRec.topics) ? memoRec.topics : [];
        const chain0 = state.chain && state.chain.length > 0 ? state.chain[0] : null;
        const budget = cfg.context && cfg.context.budgetChars ? cfg.context.budgetChars : 0;
        // v3.0p：预算 > 0 才启用检索（与「上下文预算需 > 0 才启用检索」联动语义一致）
        setProgress(rec, STAGE_FILES, 'plan');
        // P0-b：预算耗尽 → 直接跳过规划（planWebSearch 内部亦自检，双保险）
        const plan = (budget > 0 && !budgetExhausted(state)) ? await planWebSearch(text, memoText, state.scenario, chain0, state) : (budget > 0 ? (markDegraded(state, 'webplan-budget'), null) : null);
        hlog('[enhance] v3p web-plan ' + (budget <= 0 ? 'skipped budget=0' : (plan ? 'topics=' + plan.topics.map((t) => t.query).join('|') : 'none→legacy')));
        // v3.0p：规划主题与已检索主题去重（LLM 未遵从提示词时的硬过滤；过滤后为空 → 降级单 query）
        const freshPlan = plan && budget > 0 ? plan.topics.filter((t) => memoTopics.indexOf(String(t && t.query || '').trim()) === -1) : null;
        const v2 = await buildV2ContextBlock({
          llm: ctx.get('llm'),
          sessionQuery: ctx.get('sessionQuery'),
          sandboxPolicy: ctx.get('sandboxPolicy'),
          fs: ctx.get('fs'),
          timer: ctx.timer,
          chain: state.chain,
          web: ctx.get('web'),
          delta: state.memDelta,
          scenario: state.scenario,
          webPlan: freshPlan && freshPlan.length > 0 ? freshPlan : null,
          webMemo: memoText,
          // P0-b（2026-10-12）：publish 的 v2 旧管道（阶段 A 任务分析 15s / 阶段 B 2s /
          // 网络检索 10s）同属准备阶段——把主预算截止时刻交给它，内部各调用据此钳到剩余预算。
          budgetDeadline: state.budgetDeadline,
          budgetMs: state.budgetMs,
          // P0-d（2026-10-12 · 独立复核 medium）：v2 管道内的辅助调用降级回传
          // （第 5 个辅助点 v2ResolveProgress 经此暴露，不再只写 hlog）
          onDegrade: (kind) => { markDegraded(state, kind); },
        }, sessionId, text, cfg, (st, detail) => {
          rec.stage = st;
          if (detail && typeof detail === 'object') {
            rec.detailKey = detail.key || '';
            rec.detailArgs = detail.args || null;
            rec.step = detail.step || 0;
            rec.total = detail.total || 0;
          } else {
            rec.detailKey = '';
            rec.detailArgs = null;
            rec.step = 0;
            rec.total = 0;
          }
        });
        state.v2Block = v2.block;
        state.v2Log = v2.log;
        // v3.0p：跨轮检索记忆更新——仅成功命中的主题入已检索列表（失败/超时不占位），
        // 主题去重（≤WEB_MEMO_TOPICS_MAX）+ 要点摘要累积（≤WEB_MEMO_MAX，保留最新）
        const hitTopics = Array.isArray(v2.webTopics) ? v2.webTopics.filter((t) => t && t.hits > 0) : [];
        if (hitTopics.length > 0) {
          const merged = memoTopics.concat(hitTopics.map((t) => t.query)).filter((q, i, a) => q && a.indexOf(q) === i).slice(-WEB_MEMO_TOPICS_MAX);
          const memo = (memoText ? memoText + '\n' : '') + (v2.webMemoText || '');
          publishWebMemo.set(sessionId, { topics: merged, memo: memo.slice(-WEB_MEMO_MAX) });
          hlog('[enhance] v3p memo topics=' + merged.length + ' chars=' + memo.slice(-WEB_MEMO_MAX).length);
        }
      }
      // v3.2.24（规则落点 L2）：参考使用规则改为条件注入——参考块/记忆命中才追加（v3.2.20 并入 discipline 无条件，
      // 现拆为独立 REFERENCE_GUIDE 提示词文件按需加载，无参考场景省 tokens）；L0 纪律保持精简。
      if (state.v2Block !== '' || state.memoryActive) state.system = state.system + '\n\n' + REFERENCE_GUIDE;
      return state;
    }    // ---- stage: assemble——消息组装 / 日志 ----
    async function enhanceStageAssemble(state) {
      const args = state.args;
      const sessionId = state.sessionId;
      const seq = state.seq;
      const text = state.text;
      // 2026-08-18（用户需求·每模式步骤补充）：assemble 阶段开始即上报进度「组装上下文」
      if (state.rec) setProgress(state.rec, STAGE_CONTEXT);
      const cfg = state.cfg;
      const chain = state.chain;
      const system = state.system;
      const memRounds = state.memRounds;
      const memoryActive = state.memoryActive;
      const memDelta = state.memDelta;
      const v2Block = state.v2Block;
      const v2Log = state.v2Log;
      const isContinuation = state.isContinuation === true;
      const timeoutMs = state.timeoutMs;
      const maxTokens = state.maxTokens;
      const outputLimit = state.outputLimit;
      // v2.6.1：消息组装——记忆链经 buildChatMessages 成为真多轮 user/assistant 消息，
      // 最终 user 消息 = 本轮修改摘要 + 模式块 + 原文包裹；无记忆 → 单 user 消息（旧行为）。
      let memoryLog = '';
      // v2.8.0（一键发布 · 实测修正）：publish 用中性用户包装（wrapPublishText），
      // 其余模式沿用「请优化以下提示词」包装（行为不变）
      const wrappedText = state.isPublish ? wrapPublishText(text) : wrapUserText(text);
      let finalText = v2Block !== '' ? v2Block + '\n\n' + wrappedText : wrappedText;
      if (isContinuation) {
        state.system = system + '\n\n' + CONTINUE_PROMPT;
        const hint = buildMemoryDeltaHint(memDelta);
        finalText = '【本轮修改】（主要优化方向）\n' + (hint !== '' ? hint : '请基于当前草稿继续完善。') + '\n\n【当前提示词】\n"""\n' + text + '\n"""\n\n请基于以上修改继续完善，输出完整更新后的提示词。';
      }
      let messages;
      if (memoryActive) {
        const hint = buildMemoryDeltaHint(memDelta);
        if (hint !== '' && !isContinuation) finalText = hint + '\n\n' + finalText;
        const built = buildChatMessages(memRounds, finalText, 'enhance-' + sessionId + '-' + seq, cfg.context.budgetChars);
        messages = built.messages;
        memoryLog = 'memory rounds=' + memRounds.length + ' chars=' + built.memChars + ' delta=' + (hint !== '' ? 'yes' : 'none');
      } else {
        messages = [{ id: 'enhance-' + sessionId + '-' + seq, role: 'user', content: [{ type: 'text', text: finalText }], source: { kind: 'user' } }];
      }
      const modeTag = args && args.seed === true ? cfg.mode + '(seed)' : cfg.mode;
      const ctxLog = [v2Log === 'none' ? '' : v2Log, memoryLog].filter((s) => s !== '').join('+') || 'none';
      hlog('[enhance] cfg session=' + sessionId + ' mode=' + modeTag + ' ctx=' + ctxLog + ' chain=' + (chain.length > 0 ? chain.map((f) => f.provider + '/' + f.model).join(',') : '-') + ' timeout=' + timeoutMs + ' maxTokens=' + maxTokens + ' outputLimit=' + outputLimit + ' template=' + (cfg.templatePick && typeof cfg.templatePick === 'object' && cfg.templatePick[cfg.mode] ? cfg.templatePick[cfg.mode] : (cfg.templateMode === 'custom' ? 'custom' : 'builtin')));
      state.messages = messages;
      return state;
    }

    // ---- stage: llm——模型链调用 / 流式收集 / 结果清理 ----
    async function enhanceStageLlm(state) {
      const sessionId = state.sessionId;
      const seq = state.seq;
      const rec = state.rec;
      let chain = state.chain.slice();
      const system = state.system;
      const messages = state.messages;
      const isPublish = state.isPublish;
      const maxTokens = state.maxTokens;
      const outputLimit = state.outputLimit;
      let lastFailure = null;
      // 2026-08-18（用户需求·删内置兜底链）：模型链为空 → 明确报「未配置模型」（不自适应补足）
      if (chain.length === 0) {
        state.result = { ok: false, code: 'NO_MODEL', message: friendlyMessage({ code: 'NO_MODEL' }) };
        return state;
      }
      // v3.3.3（2026-08-27 用户实测·增强易断链修复）：外层 pass 循环——首轮整链耗尽后
      // 整体重试一次（最多 2 pass），瞬时限流/慢首字/网络抖动自愈；重试轮不再挂看门狗、
      // 不走探测缓存（直接真实生成），杜绝「探测判死 → 冻结整链 → 连续失败」；
      // 总预算仍由外层 timeoutMs 计时器兜底（rec.timedOut 立即中断，不无限重试）。
      for (let pass = 0; pass < 2; pass++) {
      for (let i = 0; i < chain.length; i++) {
        const entry = chain[i];
        if (rec.cancelled || rec.timedOut) {
          state.result = { ok: false, code: rec.timedOut ? 'TIMEOUT' : 'ABORTED', message: friendlyMessage({ code: rec.timedOut ? 'TIMEOUT' : 'ABORTED' }) };
          return state;
        }
        hlog('[enhance] try session=' + sessionId + ' provider=' + entry.provider + ' model=' + entry.model + (entry.reasoningEffort ? ' effort=' + entry.reasoningEffort : '') + ' seq=' + seq);
        // v3.2.4（用户需求）：模型序号 = 用户设置（fallback 链）中的位置——buildTryChain
        // 会去重/过滤导致 chain 索引偏移；用 fallback 原始序号，设置里第 N 条就显示 N（自动随数量）
        const fb = state.cfg && Array.isArray(state.cfg.fallback) ? state.cfg.fallback : [];
        let stepNum = i + 1;
        for (let fi = 0; fi < fb.length; fi++) {
          const it = fb[fi];
          if (it && typeof it === 'object' && String(it.provider).trim() === entry.provider && String(it.model).trim() === entry.model) {
            stepNum = fi + 1;
            break;
          }
        }
        setProgress(rec, STAGE_LLM, i > 0 ? 'retry' : '', null, stepNum, fb.length > 0 ? fb.length : chain.length);
        let result = null;
        let streamThrowFailure = null;
        let watchFired = false;
        // P0-a（2026-10-12 · 补退避重试）：插件直调 ctx.llm.stream() 站在官方设计上**没有可靠性层**的位置——
        // 宿主退避挂在 agent/request-error 水位（由 agent-loop 生产），插件自己消费流吃不到（官方明文：
        // 直接调用 ctx.llm.stream() 的调用方仍然只尝试一次）。此处按官方语义在其外层补一层退避重试：
        //   · 退避参数**不硬编码** —— 调 ctx.llm.providerRetryPolicy(provider) 取官方**已解析**的策略
        //     （**平铺**结构：{mode,maxRetries,retryableCodes,initialDelayMs,maxDelayMs,jitterRatio}）；
        //   · 可重试码集同样**从策略取**（policy.retryableCodes），不照抄常量；
        //   · 退避公式与官方 dsh-llm-retry localDelay 逐式一致（见 pure.js computeBackoffDelayMs）；
        //   · 策略不可得（旧宿主/未注册路由）→ 不重试，行为回到「只尝试一次」（零回归）。
        for (let attempt = 0; ; attempt++) {
          if (rec.cancelled || rec.timedOut) break;
          let stream;
          try {
            stream = llm.stream({
              provider: entry.provider,
              model: entry.model,
              ...(entry.reasoningEffort ? { reasoningEffort: entry.reasoningEffort } : {}),
              system,
              // v2.7.0（publish）：maxTokens<=0 省略字段 → provider 默认上限（不设限制）
              // v2.9.0-fix（实测确证）：reasoning 模式（带 effort）下思考过程消耗 maxTokens
              // 预算——配置的 2000 在长输入 + effort=max 时耗尽 → 空流（EMPTY_RESPONSE）；
              // 自动放宽到 >=8000（保守版；publish 九章规格长文同策略放宽——实测 maxTokens=2000 时空流，v3.2.27 修复）
              ...(entry.reasoningEffort ? { maxTokens: Math.max(maxTokens, 8000) } : (isPublish ? { maxTokens: Math.max(maxTokens, 8000) } : (maxTokens > 0 ? { maxTokens } : {}))),
              // v3.2.21（用户需求·优化结果稳定）：确定性重述任务压低 temperature——不传时用平台默认
              // （随机性高，同一输入每次结果不同）；reasoning 链节由 effort 控制，不传 temperature
              ...(entry.reasoningEffort ? {} : { temperature: 0.3 }),
              messages,
            });
          } catch (e) {
            // v3.1.3（看门狗 + 延迟连通性预检）：llm.stream 同步抛错 = 模型不可达 → 记失败走下一条
            hlog('[enhance] fail session=' + sessionId + ' model=' + entry.model + ' code=STREAM_THROW attempt=' + attempt);
            streamThrowFailure = { code: e && e.code ? String(e.code) : 'STREAM_THROW', message: String(e && e.message ? e.message : e) };
            break;
          }
          const iterator = stream[Symbol.asyncIterator]();
          rec.iterator = iterator;
          // v3.1.3（看门狗 + 延迟连通性预检）：仅首个尝试挂响应看门狗——WATCHDOG_TIMEOUT_MS 内
          // 无任何 chunk → 判首模型不通，中断当前流并进入连通性探测（探测选模型重启生成，
          // 重启不再挂看门狗，防「慢但健康」模型被反复打断成死循环）
          let watchTimer = null;
          watchFired = false;
          if (i === 0 && !state.watchdogDone) {
            // P0-c（2026-10-12）：看门狗阈值按实测 TTFT 重算（= ceil(9300×2/1000)×1000 = 19s），
          // 但**必须按剩余主预算钳制**——
            // 否则放宽阈值会掩盖真挂死（一个不响应的路由可以一直在预算内耗着）。钳制后：
            // ① 慢但健康（TTFT ≤ 9.3s 实测上界）不会被误杀；② 真无响应仍在主预算处被砍（TIMEOUT）。
            const watchBudget = remainingBudgetMs(state);
            const watchMs = watchBudget === Infinity ? WATCHDOG_TIMEOUT_MS : Math.max(0, Math.min(WATCHDOG_TIMEOUT_MS, watchBudget));
            watchTimer = ctx.timer.timeout(() => {
              watchFired = true;
              if (rec.iterator && typeof rec.iterator.return === 'function') {
                try { rec.iterator.return(); } catch (e) { /* 忽略 */ }
              }
            }, watchMs);
          }
          try {
            result = await collectStream(iterator, outputLimit, () => {
              if (watchTimer) { watchTimer(); watchTimer = null; }
            });
          } finally {
            if (watchTimer) watchTimer();
            rec.iterator = null;
          }
          if (watchFired) break;
          // ---- P0-a：退避重试判定（仅对策略声明的可重试码；watchdog/toolong/aborted/cancelled 不在此列）----
          // P0-e 联动：max-tokens 截断是**确定性**结果（同 maxTokens 重试必然再截断）——
          //   · 有实质文本 → 视为终态，break 出去由主生成点采纳（不进重试，省预算且语义正确）；
          //   · 无文本（纯思考吃满预算） → 可能是瞬时故障，才交给策略判定是否重试。
          const truncatedWithText = result && result.kind === 'maxtokens' && typeof result.text === 'string' && result.text !== '';
          if (truncatedWithText) break;
          const attemptFailure = result && (result.kind === 'error' || result.kind === 'maxtokens') ? (result.failure || null) : null;
          if (!attemptFailure) break;
          const policy = retryPolicyFor(entry.provider);
          if (!isRetryableFailure(policy, attemptFailure)) break;
          // always 语义官方无 maxRetries（不设限）；插件侧给安全上限防不收敛——
          // 尤其 timeoutMs=0（无限制）时 budgetDeadline=null，预算不构成中断（独立复核 medium）。
          const retryCap = policy.mode === 'always'
            ? RETRY_ALWAYS_SAFETY_CAP
            : (Number.isSafeInteger(policy.maxRetries) ? policy.maxRetries : 0);
          if (attempt >= retryCap) break;
          if (budgetExhausted(state)) { hlog('[enhance] retry skipped budget-exhausted code=' + attemptFailure.code); break; }
          // 平铺策略对象直接传入（官方 ResolvedRetryPolicy 无 backoff 子对象）
          const delayMs = computeBackoffDelayMs(policy, attempt + 1, Math.random);
          // 独立复审 medium（2026-10-12）：重试**不得**混进「降级」通道——
          // 「重试后成功」是瞬时故障自愈（P0-a 的目标场景），不是「上下文不完整」；
          // 混入会让常见成功路径被 UI 误标「⚠ 部分上下文不可用」，削弱降级信号可信度。
          // 故重试只记 hlog（可观测）与独立计数 rec.retries，绝不进 rec.degraded。
          if (!Array.isArray(rec.retries)) rec.retries = [];
          rec.retries.push(String(attemptFailure.code || 'unknown'));
          hlog('[enhance] retry attempt=' + (attempt + 1) + '/' + retryCap + ' code=' + attemptFailure.code + ' delay=' + Math.round(delayMs) + 'ms provider=' + entry.provider + ' seq=' + seq);
          setProgress(rec, STAGE_LLM, 'retry', { current: attempt + 1, total: retryCap }, attempt + 1, retryCap);
          await sleepMs(delayMs);
        }
        if (streamThrowFailure) {
          lastFailure = streamThrowFailure;
          continue;
        }
        if (watchFired) {
          state.watchdogDone = true;
          hlog('[enhance] watchdog no-response in ' + WATCHDOG_TIMEOUT_MS + 'ms on ' + entry.provider + '/' + entry.model + ' seq=' + seq);
          setProgress(rec, STAGE_LLM, 'probe', null, 1, chain.length);
          // 连通性探测：跳过刚挂起的首条，探测剩余链（缓存优先，每条 PROBE_TIMEOUT_MS 超时）
          const rest = chain.slice(i + 1);
          const pick = await probeFirstReachable(rest);
          if (!pick) {
            // 剩余全不通 → 回头探测挂起首条：通畅（只是慢）→ 重试一次；不通 → 全不可用
            const headOk = await probeEntry(entry);
            if (!headOk) {
              hlog('[enhance] chain all unavailable session=' + sessionId + ' last code=' + (lastFailure ? lastFailure.code : '?'));
              // v3.3.3（设计决策）：探测窗口已按实测放大（PROBE_TIMEOUT_MS=12s）——探测全败
              // = 实测全不可达（慢模型不再被误杀），立即报错不进入重试轮（避免无望的二次等待）；
              // 重试轮只覆盖生成级失败耗尽（EMPTY/STREAM_THROW/QUOTA/瞬时错误等自愈场景）。
              state.result = { ok: false, code: 'ALL_MODELS_UNAVAILABLE', message: friendlyMessage({ code: 'ALL_MODELS_UNAVAILABLE' }) };
              return state;
            }
            hlog('[enhance] watchdog retry head via ' + entry.provider + '/' + entry.model + ' seq=' + seq);
            chain = [entry];
            i = -1;
            continue;
          }
          hlog('[enhance] watchdog restart via ' + pick.provider + '/' + pick.model + ' seq=' + seq);
          chain = [pick].concat(chain.filter((e) => e !== pick && e !== entry));
          i = -1;
          continue;
        }
        if (result.kind === 'ok') {
          // v2.8.0（实测修正）：publish 剥离输出首部【场景判定】回显行（确定性，不依赖模型遵从）
          const cleaned = isPublish ? stripScenarioEcho(cleanOutput(result.text, state.text)) : cleanOutput(result.text, state.text);
          if (cleaned === '') {
            lastFailure = { code: 'EMPTY_RESPONSE', message: 'model returned empty text' };
            continue;
          }
          hlog('[enhance] ok session=' + sessionId + ' via ' + entry.model);
          state.result = { ok: true, text: cleaned, model: entry.model, ...(state.watchdogDone === true || i > 0 ? { fallbackUsed: true } : {}) };
          return state;
        }
        if (result.kind === 'toolong') {
          lastFailure = { code: 'OUTPUT_TOO_LONG', message: 'output exceeded limit' };
          continue;
        }
        // P0-e（2026-10-12）：max-tokens 截断是**官方合法** finish（不再落 EMPTY_RESPONSE 兜底）。
        // 若已收到实质文本 → 直接采纳为结果（长草稿被截断但内容可用，优于报错丢弃）；
        // 无文本（纯思考吃满预算）→ 如实报 OUTPUT_TRUNCATED（文案由 friendlyMessage 给真实原因）。
        if (result.kind === 'maxtokens') {
          const truncated = typeof result.text === 'string' ? result.text : '';
          if (truncated !== '') {
            const cleanedMt = isPublish ? stripScenarioEcho(cleanOutput(truncated, state.text)) : cleanOutput(truncated, state.text);
            // P0-e 修正（2026-10-12 · 独立复核 high）：截断文本**不得无条件采纳**——截断点可能落在
            // 指令包装中途（模型回显「请优化以下提示词："""…」），此时 cleanOutput 因包装未闭合剥不掉，
            // 会把带包装的残片当结果覆盖用户草稿（旧行为是报 EMPTY_RESPONSE、草稿保留 ⇒ 反而更安全）。
            // 采纳门槛（离线可判，不调模型）：① 剥离后非空；② 剥离后**不再含未闭合的指令包装特征**
            // （三引号/「请优化以下提示词」等 wrap 痕迹）；③ 非残片（≥8 字符）。
            // ⚠ 曾用「≥原文 10%」，实测会误伤「短输入 + 短而合法的截断输出」（过度收紧）——已回退为绝对值下限。
            // 任一不满足 → 不采纳，按 OUTPUT_TRUNCATED 如实失败（草稿保留）。
            const stillWrapped = /"""|请优化以下提示词|优化以下提示词|【用户输入】/.test(cleanedMt);
            // 残片下限：极短输入（如 4 字）不应被绝对值门槛误伤——取 min(8, 原文长度) 作下限
            const minLen = Math.min(8, Math.max(1, String(state.text || '').length));
            const longEnough = cleanedMt.length >= minLen;
            if (cleanedMt !== '' && !stillWrapped && longEnough) {
              markDegraded(state, 'output-truncated');
              hlog('[enhance] ok(truncated by max-tokens) session=' + sessionId + ' via ' + entry.model + ' chars=' + cleanedMt.length);
              state.result = { ok: true, text: cleanedMt, model: entry.model, truncated: true, ...(state.watchdogDone === true || i > 0 ? { fallbackUsed: true } : {}) };
              return state;
            }
            hlog('[enhance] truncated output rejected session=' + sessionId + ' wrapped=' + stillWrapped + ' longEnough=' + longEnough + ' chars=' + cleanedMt.length);
          }
          lastFailure = { code: 'OUTPUT_TRUNCATED', message: 'output reached the length limit and was truncated' };
          continue;
        }
        if (result.kind === 'cancelled' || result.kind === 'aborted') {
          state.result = { ok: false, code: rec.timedOut ? 'TIMEOUT' : 'ABORTED', message: friendlyMessage({ code: rec.timedOut ? 'TIMEOUT' : 'ABORTED' }) };
          return state;
        }
        hlog('[enhance] fail session=' + sessionId + ' model=' + entry.model + ' code=' + (result.failure ? result.failure.code : '?'));
        lastFailure = result.failure || { code: 'LLM_FAILED', message: 'unknown failure' };
      }
      // v3.3.3（链耗尽）：pass 0 且未被取消/超时 → 整链重试一次（watchdogDone=true 免看门狗）
      if (pass === 0 && !rec.cancelled && !rec.timedOut) {
        hlog('[enhance] chain exhausted retry pass=2 session=' + sessionId + ' last code=' + (lastFailure ? lastFailure.code : '?'));
        state.watchdogDone = true;
        continue;
      }
      hlog('[enhance] chain exhausted session=' + sessionId + ' last code=' + (lastFailure ? lastFailure.code : '?'));
      state.result = { ok: false, code: lastFailure.code || 'LLM_FAILED', message: friendlyMessage(lastFailure) };
      return state;
      }
    }

    // v3.1.3（看门狗 + 延迟连通性预检）：连通性探测——缓存优先，pingStream 短输入探测
    // （可达性：QUOTA/网络/auth/超时；探测 ≠ 生成成功，生成级失败仍由原回退链兜底）
    const probeCache = new Map();
    async function probeEntry(entry) {
      if (!entry) return false;
      const key = entry.provider + '/' + entry.model;
      const now = Date.now();
      const hit = probeCacheGet(probeCache, key, now);
      if (hit) return hit.ok === true;
      if (llm === undefined) return false;
      const ref = { current: null };
      let timedOut = false;
      const timer = ctx.timer.timeout(() => {
        timedOut = true;
        if (ref.current && typeof ref.current.return === 'function') {
          try { ref.current.return(); } catch (e) { /* 忽略 */ }
        }
      }, PROBE_TIMEOUT_MS);
      let r;
      try {
        r = await pingStream(llm, entry, ref);
      } finally {
        timer();
      }
      const ok = !timedOut && r && r.ok === true;
      probeCacheSet(probeCache, key, { ok, code: timedOut ? 'TIMEOUT' : (r ? r.code : 'LLM_FAILED') }, now);
      hlog('[enhance] probe ' + entry.provider + '/' + entry.model + ' → ' + (ok ? 'ok ' + (r ? r.latencyMs : '?') + 'ms' : (timedOut ? 'timeout' : (r ? r.code : 'LLM_FAILED'))));
      return ok;
    }
    async function probeFirstReachable(entries) {
      for (const entry of entries) {
        if (await probeEntry(entry)) return entry;
      }
      return null;
    }

    registerEnhanceStage('analyze', enhanceStageAnalyze, { priority: 100 });
    registerEnhanceStage('retrieve', enhanceStageRetrieve, { priority: 100 });
    registerEnhanceStage('assemble', enhanceStageAssemble, { priority: 100 });
    registerEnhanceStage('llm', enhanceStageLlm, { priority: 100 });

    harness.handle('enhance', async (args) => {
      const sessionId = args && typeof args.sessionId === 'string' ? args.sessionId : 'unknown';
      const seq = args && typeof args.seq === 'number' ? args.seq : -1;
      const text = args && typeof args.text === 'string' ? args.text : '';
      const key = requestKey(sessionId, seq);
      if (text.trim() === '' || text.startsWith('/')) {
        return { ok: false, code: 'GUARD', message: friendlyMessage({ code: 'GUARD' }) };
      }
      if (llm === undefined) {
        return { ok: false, code: 'NO_LLM', message: friendlyMessage({ code: 'NO_LLM' }) };
      }

      // v2.3（§7.3）：记录提前创建（入参校验后）——stage 从 prepare 起可被 progress RPC 轮询
      // v3.0r（细粒度进度反馈）：rec 扩展——startedAt/detailKey/detailArgs/step/total
      const rec = { cancelled: false, timedOut: false, iterator: null, stage: STAGE_PREPARE, startedAt: Date.now(), detailKey: '', detailArgs: null, step: 0, total: 0 };
      pending.set(key, rec);

      // M2 深化：请求状态经 Pipeline 四阶段链式传递（analyze→retrieve→assemble→llm）。
      // P0-b（2026-10-12 · 超时预算错位修复；独立复核 high 修正）：主超时计时器上移到**任何阶段之前**——
      // 准备阶段（analyze/retrieve/assemble，内含 5 处各 10–15s 的辅助调用）首次被真正限界，
      // 不再「准备阶段不设防」；辅助调用另按剩余预算钳制（helperTimeoutMs），超预算即跳过并记降级。
      // ⚠ 不劣化生成额度（复核实测过「prepare+generation 超时」的拆东墙）：总预算 = **生成额度 + 准备额度**，
      //   准备最多吃掉自己的额度 ⇒ 生成阶段仍拿满原 timeoutMs。旧行为（生成计时器后挂）等价于
      //   「准备不计费」；新行为是「准备有自己的上限」，两者在**所有原本能过的场景**下都仍然能过。
      const state = { args, sessionId, seq, text, key, rec };
      const budgetCfg = validateConfig(args && args.config);
      if (args && typeof args.mode === 'string' && MODE_KEYS.includes(args.mode)) budgetCfg.mode = args.mode;
      const genTimeoutMs = resolveEnhanceTimeoutMs(budgetCfg, buildTryChain(budgetCfg.fallback));
      const modeRow = (SKILL_MANIFEST[budgetCfg.mode] || SKILL_MANIFEST[DEFAULT_MODE]) || {};
      // 超时表由调用方传入（避免 PURE 区段内 const 的暂时性死区；见 pure.js 注释）
      const prepareBudgetMs = resolvePrepareBudgetMs(modeRow.retrieve, modeRow.sources, {
        relevanceMs: RELEVANCE_TIMEOUT_MS,
        eventsMs: V2_SEARCH_EVENTS_TIMEOUT_MS,
        workspaceMs: V2_WORKSPACE_TIMEOUT_MS,
        progressMs: V2_PROGRESS_TIMEOUT_MS,
        webPlanMs: WEB_PLAN_TIMEOUT_MS,
        webSearchMs: WEB_SEARCH_TIMEOUT_MS,
        webSearchMaxResults: WEB_SEARCH_MAX_RESULTS,
      });
      const totalBudgetMs = genTimeoutMs > 0 ? genTimeoutMs + prepareBudgetMs : 0;
      state.budgetMs = genTimeoutMs;          // 生成额度（llm 阶段语义 / 日志沿用）
      state.prepareBudgetMs = prepareBudgetMs;
      state.budgetDeadline = totalBudgetMs > 0 ? Date.now() + totalBudgetMs : null;
      // v3.1.7（用户需求·超时无限制）：timeoutMs<=0 不挂超时计时器（0 = 无限制，等待模型自然完成）
      const timeoutDisposer = totalBudgetMs > 0 ? ctx.timer.timeout(() => {
        markAndAbort(key, 'timedOut');
      }, totalBudgetMs) : null;

      try {
        await runEnhanceStages('analyze', state);
        await runEnhanceStages('retrieve', state);
        await runEnhanceStages('assemble', state);
        await runEnhanceStages('llm', state);
        // P0-d：降级清单随结果回传（结果态 UI 可见；无降级 → 不附字段，行为零变化）
        if (state.result && typeof state.result === 'object' && Array.isArray(rec.degraded) && rec.degraded.length > 0) {
          state.result.degraded = rec.degraded.slice();
        }
        return state.result;
      } catch (e) {
        herr('[enhance] unexpected error session=' + sessionId + ' seq=' + seq, e);
        return { ok: false, code: 'LLM_FAILED', message: friendlyMessage({ code: 'LLM_FAILED' }) };
      } finally {
        if (timeoutDisposer) timeoutDisposer();
        pending.delete(key);
      }
    });

    // ================= CHG-143：语音输入纠错（**独立语音增值步** · 非增强管线内的一步）=================
    // 用户第三轮架构澄清（逐字）：「…是属于语言功能的增强模块，就是这个纠错**可以独立存在**的…
    //   纠错功能打开、自动增强没打开 ⇒ 识别完成后**自动使用纠错然后就结束**；两者都开 ⇒
    //   **先纠错然后接着增强**…**并不是集成绑定在提示词增强一起的**」。
    // ⇒ 本 RPC 归属**语音链路**、触发点是**语音识别完成之后**，由 client 显式按两开关的组合调用；
    //   ⚠ **不是**增强管线的 stage（增强入口 `enhance` 一步都不碰纠错 ⇒ 手动 ✨ 天然零纠错调用）。
    // ⚠ 与增强**共用一次「增强式」模型调用式样**（chain[0] + 会话历史窗口参考），但**独立 RPC、独立预算**：
    //   不挂进 enhance 的四阶段管道，也不消费 enhance 的预算/进度槽位（不破坏既有增强链语义）。
    //
    // 参考窗口 = **最近的显式会话轮次**（读法甲 · 主持侧裁定）：与既有模式族同构
    //   （lite = 前 1 轮）；取「前 1 轮」= 最轻，合「主要为语音识别纠错」的用途。
    //   「显式」= 只取 text 块（extractHistoryConclusions 已丢弃思考/工具调用/系统注入）。
    const CORRECTION_WINDOW = [1, 1];              // 前 1 轮（lite 式）
    const CORRECTION_TIMEOUT_MS = 30000;           // 独立小调用：不与 enhance 预算耦合
    const CORRECTION_MAX_TOKENS = 4000;            // 纠错是「复述 + 局部换字」，不需要长输出
    const CORRECTION_OUTPUT_LIMIT = 16000;         // 草稿可能很长 ⇒ 不截断过紧

    async function fetchCorrectionHistory(sessionId) {
      const sq = ctx.get('sessionQuery');
      if (!sq || typeof sq.readSurface !== 'function') {
        hlog('[correction] history skipped no-readSurface');
        return '';
      }
      // 超时保护与既有历史腿同款（race + dispose；超时即不再等，不阻断纠错）
      const waitAbort = startWaitAbort(ctx.timer, V2_SEARCH_EVENTS_TIMEOUT_MS);
      try {
        const surface = await waitAbort.race(sq.readSurface(sessionId));
        if (waitAbort.timedOut()) { hlog('[correction] history timeout'); return ''; }
        const events = extractHistoryConclusions(surface && surface.events);
        const lines = splitHistoryRounds(events, CORRECTION_WINDOW[0], CORRECTION_WINDOW[1]);
        const text = lines.join('\n');
        hlog('[correction] history rounds=' + CORRECTION_WINDOW[0] + '-' + CORRECTION_WINDOW[1] + ' events=' + events.length + ' chars=' + text.length);
        return text;
      } catch (e) {
        hlog('[correction] history failed', e && e.message ? e.message : e);
        return '';
      } finally {
        waitAbort.dispose();
      }
    }

    // ================= 纠错服务端守卫（2026-10-17 · 纠错服务端守卫批 · 第 ① 件）=================
    // 病历（真机复核批实测）：`voice/correct` **不读** `voice.correction.enabled` —— 开关此前**只**由
    //   client 的 `runCorrectionThenMaybeEnhance` 拦截 ⇒ 把开关置 false 后直调该 RPC **2/2 次**
    //   都走到模型（本批只读复现，见报告 §②；上一批读数是 10/10，本批**未重跑 10 次**）。
    //
    // 本席处置（用户裁定，作业书 §1.2）：**服务端补守卫**；client 那道**保留**（纵深防御两层，不是冗余）。
    //
    // ⚠⚠ **配置从哪读（本席自查修正的关键一处，见报告 §④）**：
    //   起初本席写成读 `args.config`（随请求带来的配置），**实测发现那是错的** ——
    //   client 的调度口传的是 `configState`（**增强配置**），其形状里**既无 `voice` 也无 `correction`**
    //   （`src/client/state.js` 的 `cloneDefaults()` 逐字无这两个键）⇒ 若读它，
    //   **开关打开时也会被判成"关"** ⇒ 把可用功能**永久关死**（正是「拆东墙补西墙」）。
    //   ⇒ 正解：读**服务端已归一化**的配置 —— `harness.readVoiceConfig()`
    //     = `rpcConfig.readConfig()`（磁盘那一份）→ `asr.sanitizeVoiceCfg()`（host 白名单唯一实现）。
    //     ⚠ 这条路径**不是**本批新造的：两者都是既有函数，本批只接线（`lib/index.cjs` 注入），
    //       故**没有**"同一事实第二份实现"（`M-3`）。
    //
    // ⚠ 三条纪律（逐条对齐作业书原文）：
    //   ① **配置走已归一化的既有路径**：`readVoiceConfig()` ⇒ 返回的是 `sanitizeVoiceCfg` 的产物，
    //      取形已是 `=== true` 的布尔；本处再取 `=== true` 是**同形加固**（不是第二份解析）。
    //      若该面不可用（测试夹具未注入 / 读盘失败）⇒ **回退**到请求随行的 `args.config`
    //      （`voice.correction` 或顶层 `correction` 两种包装位置，取形式逐字相同）——
    //      ⚠ 该回退**只服务于"无磁盘面的调用方"**，产品链路上永远走第一路。
    //   ② **取形须 `=== true`**（与 `mergeVoice` / `sanitizeVoiceCfg` 同形）——⛔ 不得写成 `!== false`，
    //      那会把「缺省」读成「开」，与本开关「缺省=关」的语义相反。
    //   ③ **fail-closed**：读不到 ⇒ 按「关」处理，**但必须在响应里可见**
    //      （`skipped` + `code` + `skippedBy`），不得静默。
    //
    // ★ 返回值语义（关键设计，承正本 §7.7「不得静默失效」· R12 诊断口径）：
    //   「没跑因开关」与「跑了没事」**必须可判** ⇒ 跳过时返回
    //     `{ ok: true, skipped: true, skippedBy: <原因>, code: 'CORRECTION_DISABLED', text, message }`
    //   ⛔ 不得伪造成 `changed:false` 的「正常无改动」（那会让「关了」与「没错字」同形）——
    //      `changed` 在跳过时**故意缺位**（缺位即"没跑过"）。
    //   为什么 `ok: true`：守卫**不是失败**（是用户的选择），调用方不该把它当错误重试/报错；
    //   区分点是 `skipped` 与 `code`，不是 `ok`。
    const CORRECTION_DISABLED_CODE = 'CORRECTION_DISABLED';
    const CORRECTION_ENABLED_REASON = 'correction.enabled';
    // 取形：`=== true`（与 `sanitizeVoiceCfg`／`mergeVoice` 同形）；读不到即 false（fail-closed）。
    function correctionEnabledOf(rawCfg) {
      const c = rawCfg && typeof rawCfg === 'object' ? rawCfg : null;
      if (!c) return false;                       // fail-closed
      const top = c.correction;
      if (top && typeof top === 'object') return top.enabled === true;
      const v = c.voice;
      if (v && typeof v === 'object' && v.correction && typeof v.correction === 'object') return v.correction.enabled === true;
      return false;                               // 缺省 = 关（与两侧白名单同口径）
    }
    // 读到"开关真值 + 来源"（来源进响应 `skippedBy`，让"从哪读的"也可见）。
    // 优先**服务端已归一化**的 face；缺位才回退请求随行 config（见上方 ① 的说明）。
    function resolveCorrectionSwitch(argsCfg) {
      let face = null;
      try {
        face = (harness && typeof harness.readVoiceConfig === 'function') ? harness.readVoiceConfig() : null;
      } catch (e) { face = null; }
      if (face && typeof face === 'object') {
        return { on: correctionEnabledOf(face) === true, from: 'host-normalized' };
      }
      // 回退：无磁盘面（单测夹具/非 bundle 载体）。⚠ 这只在 face 缺位时发生。
      return { on: correctionEnabledOf(argsCfg) === true, from: 'request-config' };
    }

    async function runCorrection(args) {
      const sessionId = args && typeof args.sessionId === 'string' ? args.sessionId : 'unknown';
      const text = args && typeof args.text === 'string' ? args.text : '';
      if (text.trim() === '') return { ok: false, code: 'GUARD', message: friendlyMessage({ code: 'GUARD' }) };
      if (llm === undefined) return { ok: false, code: 'NO_LLM', message: friendlyMessage({ code: 'NO_LLM' }) };
      const cfg = validateConfig(args && args.config);
      // ⚠ 守卫位置纪律：必须在**参数校验之后**（GUARD/NO_LLM 的既有语义不抢跑）、
      //   且在**任何模型动作之前**（chain 建立/历史读取/stream 调用都不得发生）——
      //   「开关关闭 ⇒ 不调模型」的判据就是「走到这里就 return」。
      //   取形来源 = `resolveCorrectionSwitch()`：**优先服务端已归一化**的 face
      //   （`harness.readVoiceConfig()` ⇒ `readConfig` → `sanitizeVoiceCfg`，两者都是既有函数，本批只接线）；
      //   仅当该 face 缺位（单测夹具 / 非 bundle 载体）才回退请求随行的 `args.config`。
      //   ⚠ 回退**不是**第二份语义：取形式逐字相同（`=== true`），只是包装位置不同。
      //   缺省/读不到 ⇒ false ⇒ 跳过且**可见**（`switchFrom` 写明是哪一侧判的）。
      const corrSwitch = resolveCorrectionSwitch(args && args.config);
      if (corrSwitch.on !== true) {
        // 跳过原因点名**是哪一侧**判的关（host 归一化面 / 请求随行 config）—— 便于排查"读错源"。
        hlog('[correction] skipped session=' + sessionId + ' from=' + corrSwitch.from);
        // ★ 返回值语义：「因开关没跑」必须与「跑了但没改动」**可判** ⇒ skipped/code 双标记。
        //   ⛔ 不给 `changed`（缺位 = 没跑过），⛔ 不返回 ok:false（守卫不是失败）。
        return {
          ok: true,
          skipped: true,
          skippedBy: CORRECTION_ENABLED_REASON,
          switchFrom: corrSwitch.from,
          code: CORRECTION_DISABLED_CODE,
          text,
          message: friendlyMessage({ code: CORRECTION_DISABLED_CODE }),
        };
      }
      const chain = buildTryChain(cfg.fallback);
      if (chain.length === 0) return { ok: false, code: 'NO_MODEL', message: friendlyMessage({ code: 'NO_MODEL' }) };
      // 参考窗口失败 ⇒ 空参考（纠错仍可依据草稿本身与判据①–④执行，降级不阻断）
      const historyText = await fetchCorrectionHistory(sessionId);
      const system = CORRECTION_PROMPT.replace('{history}', historyText);
      // ⚠ 与「判定类小调用」同款：**剥离 reasoningEffort**（纠错是字词级判定，无需深度思考；
      //   effort 思考会消耗小预算输出并放大耗时）。⚠ 但**保留 temperature=0.3**（确定性重述）。
      let lastFailure = null;
      for (let i = 0; i < chain.length; i++) {
        const entry = chain[i];
        let timedOut = false;
        let abortIterator = null;
        let settleTimeout = null;
        const gate = new Promise((resolve) => { settleTimeout = resolve; });
        const fireAbort = () => {
          timedOut = true;
          if (abortIterator && typeof abortIterator.return === 'function') {
            try { abortIterator.return(); } catch (e) { /* 忽略 */ }
          }
          try { settleTimeout({ kind: 'aborted', aborted: true }); } catch (e) { /* 忽略 */ }
        };
        const timer = ctx.timer.timeout(fireAbort, CORRECTION_TIMEOUT_MS);
        try {
          hlog('[correction] try session=' + sessionId + ' provider=' + entry.provider + ' model=' + entry.model);
          const stream = llm.stream({
            provider: entry.provider,
            model: entry.model,
            maxTokens: CORRECTION_MAX_TOKENS,
            temperature: 0.3,
            system,
            messages: [{
              id: 'correction-' + sessionId,
              role: 'user',
              content: [{ type: 'text', text }],
              source: { kind: 'user' },
            }],
          });
          const iterator = stream[Symbol.asyncIterator]();
          abortIterator = iterator;
          const collectP = collectStream(iterator, CORRECTION_OUTPUT_LIMIT);
          collectP.catch(() => { /* 落败方 */ });
          const result = await Promise.race([collectP, gate]);
          if (!timedOut && result.kind === 'ok') {
            const out = cleanOutput(result.text, text);
            if (typeof out === 'string' && out.trim() !== '') {
              hlog('[correction] ok session=' + sessionId + ' chars=' + out.length + ' history=' + historyText.length);
              return { ok: true, text: out, provider: entry.provider, model: entry.model, historyChars: historyText.length, changed: out !== text, fallbackUsed: i > 0 };
            }
            lastFailure = { code: 'EMPTY_RESPONSE' };
          } else {
            lastFailure = timedOut ? { code: 'TIMEOUT' }
              : (result.kind === 'maxtokens' ? { code: 'OUTPUT_TRUNCATED' }
              : (result.failure || { code: 'EMPTY_RESPONSE' }));
          }
        } catch (e) {
          lastFailure = { code: e && e.code ? String(e.code) : 'STREAM_THROW', message: String(e && e.message ? e.message : e) };
          hlog('[correction] stream failed code=' + lastFailure.code);
        } finally {
          try { timer(); } catch (e) { /* 忽略 */ }
          if (abortIterator && typeof abortIterator.return === 'function') {
            try { abortIterator.return(); } catch (e) { /* 忽略 */ }
          }
        }
        const code = lastFailure ? lastFailure.code : 'UNKNOWN';
        // 超时/截断/取消 ⇒ 确定性结果，不换下一条（省预算且语义正确）；其余（含 STREAM_THROW）走下一条
        if (code === 'TIMEOUT' || code === 'ABORTED' || code === 'OUTPUT_TRUNCATED') break;
      }
      const code = lastFailure && lastFailure.code ? lastFailure.code : 'LLM_FAILED';
      hlog('[correction] failed session=' + sessionId + ' code=' + code);
      return { ok: false, code, message: friendlyMessage({ code }) };
    }

    harness.handle('voice/correct', async (args) => {
      try {
        return await runCorrection(args);
      } catch (e) {
        herr('[correction] unexpected error', e);
        return { ok: false, code: 'LLM_FAILED', message: friendlyMessage({ code: 'LLM_FAILED' }) };
      }
    });

    harness.handle('cancel', async (args) => {
      const sessionId = args && typeof args.sessionId === 'string' ? args.sessionId : 'unknown';
      const seq = args && typeof args.seq === 'number' ? args.seq : -1;
      markAndAbort(requestKey(sessionId, seq), 'cancelled');
      return { ok: true };
    });


    ctx.effect(() => () => {
      for (const key of [...pending.keys()]) {
        const rec = pending.get(key);
        if (rec && rec.iterator && typeof rec.iterator.return === 'function') {
          try { rec.iterator.return(); } catch (e) { /* 忽略 */ }
        }
      }
    });
  },
};